INSERT INTO `bh_admins` VALUES (1, 'spr', '$argon2id$v=19$m=65536,t=4,p=1$Vy93TjVJUXloTExsMkpNag$uq50emrpl1C0b3jttbeXpjfqPzHzAbUVzYOZwxcZv94', 'admin', '2026-11-21 14:33:31', NULL, '2026-11-21 18:07:28');
INSERT INTO `bh_concepts` VALUES (39, 'unclosed-brackets', 'Unclosed brackets', 'Every opening bracket needs a matching closing one.', '## What it is\n\nBrackets - `(`, `[`, `{` - always come in matching pairs. Python keeps reading until it finds the close.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: \'(\' was never closed\n```\n\n## How to spot it\n\nCount opening and closing brackets on the line Python points to - they should match.\n\n## How to fix it\n\nAdd the missing closing bracket in the right place.\n\n## Try it\n\n```python run\nprint(\"Hello\")\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (40, 'strings-quotes', 'Strings and quotes', 'A string needs matching quote marks at both ends.', '## What it is\n\nA string literal starts and ends with the same kind of quote mark, `\"` or `\'`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: unterminated string literal\n```\n\n## How to spot it\n\nCount quote marks in pairs, the same way you\'d count brackets.\n\n## How to fix it\n\nAdd the missing closing quote mark.\n\n## Try it\n\n```python run\ngreeting = \"Hello, world!\"\nprint(greeting)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (41, 'block-syntax', 'Colons and blocks', 'Every block header (if, for, while, def, class...) ends in a colon.', '## What it is\n\nAny line that starts an indented block - `if`, `elif`, `else`, `for`, `while`, `def`, `class`, `try`, `except` - must end with a colon `:`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: expected \':\'\n```\n\nPython points at the end of the line that\'s missing it.\n\n## How to spot it\n\nScan every line that should open a block. Does it end in `:`?\n\n## How to fix it\n\nAdd the colon at the end of the header line.\n\n## Try it\n\n```python run\nfor i in range(3):\n    print(i)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (42, 'indentation', 'Indentation', 'Python uses indentation, not brackets, to show block structure.', '## What it is\n\nAfter a colon-ended line, the body must be indented one level in, consistently.\n\n## What it looks like when it goes wrong\n\n```\nIndentationError: expected an indented block\nIndentationError: unexpected indent\nTabError: inconsistent use of tabs and spaces in indentation\n```\n\n## How to spot it\n\nCompare a line\'s indentation to its neighbours - are they using the same character (spaces, not tabs) and the same amount?\n\n## How to fix it\n\nRe-indent consistently, using spaces throughout.\n\n## Try it\n\n```python run\ndef double(n):\n    return n * 2\n\nprint(double(5))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (43, 'case-sensitivity', 'Case sensitivity', 'Print, print and PRINT are three different names to Python.', '## What it is\n\nPython treats names with different capitalisation as completely different names.\n\n## What it looks like when it goes wrong\n\n```\nNameError: name \'Print\' is not defined\n```\n\n## How to spot it\n\nIf a `NameError` names something that looks like a familiar built-in or keyword, check its capitalisation.\n\n## How to fix it\n\nMatch the exact case Python expects - built-ins and keywords are lowercase.\n\n## Try it\n\n```python run\nprint(\"case matters\")\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (44, 'assignment-vs-comparison', 'Assignment vs comparison', '= stores a value; == asks if two values are equal.', '## What it is\n\n`=` assigns a value to a name. `==` compares two values and gives back `True` or `False`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax. Maybe you meant \'==\' instead of \'=\'?\n```\n\n## How to spot it\n\nLook inside any `if` or `while` condition for a single `=`.\n\n## How to fix it\n\nChange it to `==` if you\'re comparing, not assigning.\n\n## Try it\n\n```python run\nx = 5\nif x == 5:\n    print(\"five\")\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (45, 'keywords', 'Python\'s keywords', 'Keywords are fixed, exact words - elif, not elseif.', '## What it is\n\nPython has a fixed set of reserved words (`if`, `elif`, `else`, `for`, `in`, `and`, `or`, `not`, and more) that must be spelled exactly.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nIf you\'ve used another language before, double-check Python\'s exact spelling rather than assuming it matches.\n\n## How to fix it\n\nUse Python\'s real keyword (e.g. `elif`, not `elseif`).\n\n## Try it\n\n```python run\nscore = 72\nif score >= 50:\n    print(\"Pass\")\nelif score >= 0:\n    print(\"Fail\")\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (46, 'bracket-types', 'Bracket types', '(), [] and {} each mean something different.', '## What it is\n\n`()` calls a function or groups an expression. `[]` indexes into a sequence or builds a list. `{}` builds a set or dictionary.\n\n## What it looks like when it goes wrong\n\n```\nTypeError: \'builtin_function_or_method\' object is not subscriptable\n```\n\n## How to spot it\n\nAsk: am I calling something, or indexing into something? That decides which bracket.\n\n## How to fix it\n\nUse `()` to call a function or method, `[]` to index.\n\n## Try it\n\n```python run\nword = \"hello\"\nprint(word.upper())\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (47, 'function-syntax', 'Function definition syntax', 'def name(params): is the required shape.', '## What it is\n\nA function definition always follows the shape `def name(parameters):`.\n\n## What it looks like when it goes wrong\n\n```\nSyntaxError: invalid syntax\n```\n\n## How to spot it\n\nCheck every `def` line has all four pieces: `def`, a name, parentheses, and a colon.\n\n## How to fix it\n\nAdd whichever piece is missing.\n\n## Try it\n\n```python run\ndef square(n):\n    return n * n\n\nprint(square(4))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (48, 'names-and-scope', 'Names and scope', 'A name only exists once it\'s been created, exactly as spelled.', '## What it is\n\nPython only recognises a name once something has assigned it - and assigning to a name anywhere inside a function makes Python treat it as local for the whole function.\n\n## What it looks like when it goes wrong\n\n```\nNameError: name \'x\' is not defined\nUnboundLocalError: cannot access local variable \'x\' where it is not associated with a value\n```\n\n## How to spot it\n\nCompare the name letter-by-letter against where it\'s created, and check whether it\'s assigned anywhere else in the same function.\n\n## How to fix it\n\nFix the typo, or add `global name` if the function genuinely needs to update a module-level variable.\n\n## Try it\n\n```python run\ncount = 0\n\ndef increment():\n    global count\n    count += 1\n    return count\n\nprint(increment())\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (49, 'types-and-conversion', 'Types and conversion', 'Values have types, and some operations need matching types.', '## What it is\n\nEvery value has a type (`str`, `int`, `float`...). Some operators behave differently - or refuse to work at all - depending on the types involved.\n\n## What it looks like when it goes wrong\n\n```\nTypeError: can only concatenate str (not \"int\") to str\nValueError: invalid literal for int() with base 10: \'3.5\'\n```\n\n## How to spot it\n\nCheck the types of the values either side of an operator, especially `+`.\n\n## How to fix it\n\nConvert explicitly with `str()`, `int()`, or `float()` as needed.\n\n## Try it\n\n```python run\nage = 17\nprint(\"Age: \" + str(age))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (50, 'indexing', 'Indexing', 'A list of length n has valid indexes 0 through n - 1.', '## What it is\n\nList and string positions are counted from `0`. The last valid index is `len(x) - 1`.\n\n## What it looks like when it goes wrong\n\n```\nIndexError: list index out of range\n```\n\n## How to spot it\n\nCheck the index against the list\'s actual length, especially at the start and end.\n\n## How to fix it\n\nUse `len(x) - 1` for the last item, and guard against empty sequences.\n\n## Try it\n\n```python run\nitems = [10, 20, 30]\nprint(items[len(items) - 1])\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (51, 'dictionaries', 'Dictionaries', 'dict[key] crashes if the key is missing; .get() does not.', '## What it is\n\nA dictionary looks up values by key. `d[key]` crashes if the key isn\'t present; `d.get(key, default)` doesn\'t.\n\n## What it looks like when it goes wrong\n\n```\nKeyError: \'colour\'\n```\n\n## How to spot it\n\nCheck whether the key being looked up is guaranteed to exist.\n\n## How to fix it\n\nUse `.get(key, default)` when the key might be missing.\n\n## Try it\n\n```python run\ncolours = {\"apple\": \"red\"}\nprint(colours.get(\"banana\", \"unknown\"))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (52, 'zero-division-and-guards', 'Dividing by zero (and guarding against it)', 'Check a count isn\'t zero before you divide by it.', '## What it is\n\nDividing (or using `%`) by zero always crashes in Python.\n\n## What it looks like when it goes wrong\n\n```\nZeroDivisionError: division by zero\n```\n\n## How to spot it\n\nLook at what\'s on the right of `/` or `%` - could it ever be zero? An empty list\'s length is the classic case.\n\n## How to fix it\n\nAdd a guard: check the value before dividing.\n\n## Try it\n\n```python run\nscores = []\nif len(scores) == 0:\n    print(\"No scores yet\")\nelse:\n    print(sum(scores) / len(scores))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (53, 'input-validation', 'Validating input', 'Text from input() or elsewhere might not be in the shape you expect.', '## What it is\n\nAny value that comes from outside your code - `input()`, a file, a user - might not be in the format your code assumes.\n\n## What it looks like when it goes wrong\n\n```\nValueError: invalid literal for int() with base 10: \'abc\'\n```\n\n## How to spot it\n\nAsk: what happens if this value isn\'t what I expect?\n\n## How to fix it\n\nConvert carefully (e.g. via `float()` before `int()`), and consider checking the value before using it.\n\n## Try it\n\n```python run\ntext = \"42\"\nprint(int(text) * 2)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (54, 'return-values', 'Return values', 'A function without a return gives back None.', '## What it is\n\nA function only gives back a value if it hits a `return` statement. Otherwise it implicitly returns `None`.\n\n## What it looks like when it goes wrong\n\nNo error - just `None` where you expected a real value, or a crash later when something tries to use that `None`.\n\n## How to spot it\n\nIf a function\'s result always seems to be `None`, check every path through it for a `return`.\n\n## How to fix it\n\nAdd the missing `return`.\n\n## Try it\n\n```python run\ndef add(a, b):\n    return a + b\n\nprint(add(2, 3))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (55, 'function-calls', 'Function calls and arguments', 'A call must supply exactly the arguments the definition expects.', '## What it is\n\nA function\'s parameter list is a contract - every call must match it (unless defaults are used).\n\n## What it looks like when it goes wrong\n\n```\nTypeError: greet() missing 1 required positional argument: \'last_name\'\n```\n\n## How to spot it\n\nCompare the `def` line to every place the function is called or tested.\n\n## How to fix it\n\nAdd or remove parameters so the definition matches how it\'s actually used.\n\n## Try it\n\n```python run\ndef greet(first_name, last_name):\n    return \"Hello, \" + first_name + \" \" + last_name\n\nprint(greet(\"Ada\", \"Lovelace\"))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (56, 'off-by-one', 'Off-by-one errors', 'Loops and ranges that stop one step too early or too late.', '## What it is\n\nA loop, range or boundary check that\'s out by exactly one - the most common logic bug in programming.\n\n## What it looks like when it goes wrong\n\nNo error at all - just a result that\'s slightly wrong, often missing the first or last item.\n\n## How to spot it\n\nTest with the smallest possible input by hand and check the first and last values a loop actually touches.\n\n## How to fix it\n\nAdjust the range, comparison operator, or starting value so the boundary is handled correctly.\n\n## Try it\n\n```python run\nfor i in range(1, 5):\n    print(i)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (57, 'range-function', 'How range() works', 'range(a, b) includes a but stops before b.', '## What it is\n\n`range(a, b)` produces `a, a+1, ..., b-1` - it always stops one short of `b`.\n\n## What it looks like when it goes wrong\n\nA loop that should include the last number doesn\'t.\n\n## How to spot it\n\nPrint `list(range(a, b))` for small numbers and check what\'s actually in it.\n\n## How to fix it\n\nUse `range(a, b + 1)` when you need `b` included.\n\n## Try it\n\n```python run\nprint(list(range(1, 5)))\nprint(list(range(1, 6)))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (58, 'integer-vs-float-division', 'Integer vs float division', '/ gives the exact result; // rounds down and discards the remainder.', '## What it is\n\n`/` always gives the exact, possibly-fractional result. `//` rounds down to a whole number.\n\n## What it looks like when it goes wrong\n\nNo error - just a result missing its fractional part.\n\n## How to spot it\n\nTest with numbers that don\'t divide evenly.\n\n## How to fix it\n\nUse `/` when you need the exact value, `//` only when you deliberately want to discard the remainder.\n\n## Try it\n\n```python run\nprint(7 / 2)\nprint(7 // 2)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (59, 'operator-precedence', 'Operator precedence', 'Multiplication and division happen before addition and subtraction.', '## What it is\n\nPython follows the normal maths order of operations unless brackets say otherwise.\n\n## What it looks like when it goes wrong\n\nNo error - just a calculation that doesn\'t match what you meant.\n\n## How to spot it\n\nWork through the calculation by hand, following the actual order Python would use.\n\n## How to fix it\n\nAdd brackets to make the intended order explicit.\n\n## Try it\n\n```python run\na, b = 4, 6\nprint((a + b) / 2)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (60, 'boolean-logic', 'and, or, and boolean logic', 'and needs both sides true; or needs just one.', '## What it is\n\n`and` is true only if both sides are true. `or` is true if either side is true.\n\n## What it looks like when it goes wrong\n\nA validator accepts things it shouldn\'t (or rejects things it shouldn\'t).\n\n## How to spot it\n\nCheck every `or` in a validator - would `and` be more correct?\n\n## How to fix it\n\nSwap `or` for `and` (or vice versa) to match the intended rule.\n\n## Try it\n\n```python run\nname = \"ada\"\nprint(3 <= len(name) <= 20)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (61, 'loops-and-return', 'Loops and return', 'return exits the function immediately, from wherever it is.', '## What it is\n\n`return` ends the function right away. Placed inside a loop by mistake, it can end a search after just one item.\n\n## What it looks like when it goes wrong\n\nA search stops too early, missing items later in the loop.\n\n## How to spot it\n\nCheck a `return`\'s indentation - is it inside the loop, or after it?\n\n## How to fix it\n\nMove the `return` to the correct indentation level.\n\n## Try it\n\n```python run\ndef find_first_even(nums):\n    for n in nums:\n        if n % 2 == 0:\n            return n\n    return None\n\nprint(find_first_even([1, 3, 4, 5]))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (62, 'accumulators', 'Accumulators', 'An accumulator needs resetting at the start of each new thing it sums.', '## What it is\n\nAn accumulator variable builds up a running total. It needs to start fresh whenever a new total should begin.\n\n## What it looks like when it goes wrong\n\nTotals creep upward, adding onto the previous one instead of starting over.\n\n## How to spot it\n\nCheck where the accumulator is reset to its starting value - outside the loop, or inside it?\n\n## How to fix it\n\nMove the reset inside the loop that should restart it each time.\n\n## Try it\n\n```python run\nfor lst in [[1, 2], [3, 4]]:\n    total = 0\n    for n in lst:\n        total += n\n    print(total)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (63, 'loop-termination', 'Loop termination', 'Every while loop needs something that moves its condition towards false.', '## What it is\n\nA `while` loop keeps running until its condition becomes false - something inside it must actually change that condition.\n\n## What it looks like when it goes wrong\n\nThe run is stopped for taking too long - a classic infinite loop.\n\n## How to spot it\n\nFind the line that updates the condition\'s variable. If there isn\'t one, that\'s the bug.\n\n## How to fix it\n\nAdd the missing update (like `n -= 1`).\n\n## Try it\n\n```python run\nn = 3\nwhile n > 0:\n    print(n)\n    n -= 1\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (64, 'shadowing-builtins', 'Shadowing built-ins', 'Naming a variable sum or list hides the built-in function of the same name.', '## What it is\n\nPython lets you name a variable the same as a built-in function, but doing so hides the built-in for the rest of that scope.\n\n## What it looks like when it goes wrong\n\n```\nTypeError: \'int\' object is not callable\n```\n\n## How to spot it\n\nIf a `TypeError` says something isn\'t callable, check if a variable has shadowed a built-in name.\n\n## How to fix it\n\nRename the variable to something that isn\'t a built-in function name.\n\n## Try it\n\n```python run\nnumbers = [1, 2, 3]\nprint(sum(numbers))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (65, 'mutating-while-iterating', 'Mutating while iterating', 'Changing a list or dict while looping over it can skip items or crash.', '## What it is\n\nAdding or removing items from a collection while iterating over it directly can cause skipped items (lists) or a crash (dicts).\n\n## What it looks like when it goes wrong\n\n```\nRuntimeError: dictionary changed size during iteration\n```\n\nOr, for lists: items are silently skipped with no error at all.\n\n## How to spot it\n\nCheck whether the loop you\'re modifying is the same collection you\'re looping over.\n\n## How to fix it\n\nBuild a new collection (e.g. with a list comprehension) or loop over a copy (`list(d.keys())`).\n\n## Try it\n\n```python run\nnums = [1, -2, -3, 4]\nprint([n for n in nums if n >= 0])\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (66, 'string-methods', 'String methods and case', 'Character comparisons are case-sensitive.', '## What it is\n\n`\'A\' == \'a\'` is `False` - comparisons are case-sensitive unless you normalise case yourself.\n\n## What it looks like when it goes wrong\n\nNo error - just uppercase (or lowercase) input silently not matching.\n\n## How to spot it\n\nTest with a mix of uppercase and lowercase input.\n\n## How to fix it\n\nUse `.lower()` or `.upper()` on both sides before comparing.\n\n## Try it\n\n```python run\nprint(\"A\".lower() in \"aeiou\")\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (67, 'mutable-defaults', 'Mutable default arguments', 'A default list or dict is created once, not fresh on every call.', '## What it is\n\nA default argument value is evaluated exactly once, when `def` runs - not fresh on every call.\n\n## What it looks like when it goes wrong\n\nA list (or dict) \"remembers\" items from previous calls that didn\'t supply their own.\n\n## How to spot it\n\nCheck any default value that\'s a list, dict, or other mutable object.\n\n## How to fix it\n\nDefault to `None`, and create the real empty value inside the function body.\n\n## Try it\n\n```python run\ndef add_item(item, basket=None):\n    if basket is None:\n        basket = []\n    basket.append(item)\n    return basket\n\nprint(add_item(\"apple\"))\nprint(add_item(\"banana\"))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (68, 'aliasing-and-copying', 'Aliasing and copying', 'Assigning a list to a new name does not copy it.', '## What it is\n\n`b = a` makes `b` another name for the exact same list object - not a copy.\n\n## What it looks like when it goes wrong\n\nChanging one variable unexpectedly changes another.\n\n## How to spot it\n\nAsk: do I need a genuinely separate list, or just another name for the same one?\n\n## How to fix it\n\nUse `.copy()`, `list(...)`, or a comprehension to create an independent list.\n\n## Try it\n\n```python run\noriginal = [1, 2, 3]\ncopy = original.copy()\ncopy[0] = 99\nprint(original)\nprint(copy)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (69, 'recursion', 'Recursion and base cases', 'Every recursive function needs a condition where it stops calling itself.', '## What it is\n\nA recursive function calls itself with a smaller version of the problem, until a base case stops the chain.\n\n## What it looks like when it goes wrong\n\n```\nRecursionError: maximum recursion depth exceeded\n```\n\n## How to spot it\n\nCheck for a condition that returns without calling itself again.\n\n## How to fix it\n\nAdd the missing base case.\n\n## Try it\n\n```python run\ndef count_down(n):\n    if n <= 0:\n        print(\"Done!\")\n        return\n    print(n)\n    count_down(n - 1)\n\ncount_down(3)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (70, 'binary-search', 'Binary search bounds', 'The search range must shrink every pass, or it can loop forever.', '## What it is\n\nBinary search repeatedly halves a sorted range until it finds the target or the range is empty.\n\n## What it looks like when it goes wrong\n\nThe search never finishes when the target isn\'t present - the range stops shrinking.\n\n## How to spot it\n\nTrace through a search for a missing value by hand, checking the bounds actually move each pass.\n\n## How to fix it\n\nMove bounds past `mid` (`mid + 1` / `mid - 1`), not onto it.\n\n## Try it\n\n```python run\ndef binary_search(items, target):\n    low, high = 0, len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n\nprint(binary_search([1, 3, 5, 7], 5))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (71, 'closures', 'Closures and late binding', 'A lambda looks up a loop variable when called, not when created.', '## What it is\n\nFunctions created inside a loop share the same loop variable - they don\'t each get a frozen copy of its value at creation time.\n\n## What it looks like when it goes wrong\n\nEvery function created in the loop seems to return the same (final) value.\n\n## How to spot it\n\nCheck whether a value used inside a lambda or nested function comes from an enclosing loop variable.\n\n## How to fix it\n\nCapture the current value with a default argument: `lambda x=x: ...`.\n\n## Try it\n\n```python run\nmakers = [lambda i=i: i for i in range(3)]\nprint([m() for m in makers])\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (72, 'iterators-and-generators', 'Iterators and generators', 'A generator can only be stepped through once.', '## What it is\n\nA generator expression produces values lazily and doesn\'t remember them - once consumed, it\'s exhausted.\n\n## What it looks like when it goes wrong\n\nListing the same generator a second time gives an empty result.\n\n## How to spot it\n\nCheck whether something that needs reading more than once is a generator or a list.\n\n## How to fix it\n\nUse a list comprehension `[...]` instead of a generator expression `(...)` if you need to iterate more than once.\n\n## Try it\n\n```python run\nevens = [n for n in range(10) if n % 2 == 0]\nprint(list(evens))\nprint(list(evens))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (73, 'floating-point', 'Floating-point precision', 'Most decimal fractions cannot be represented exactly in binary.', '## What it is\n\n`float` values are stored in binary, and most decimal fractions (like 0.1) can\'t be represented exactly - leading to tiny rounding errors.\n\n## What it looks like when it goes wrong\n\n`0.1 + 0.2 == 0.3` is `False` - an exact-equality check between floats silently fails.\n\n## How to spot it\n\nAny `==` comparison between floats is suspect.\n\n## How to fix it\n\nUse `math.isclose(a, b)` instead of `==`.\n\n## Try it\n\n```python run\nimport math\nprint(0.1 + 0.2 == 0.3)\nprint(math.isclose(0.1 + 0.2, 0.3))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (74, 'sorting', 'Sorting', 'sorted() defaults to ascending order.', '## What it is\n\n`sorted()` arranges items smallest-to-largest by default, using `key` to decide what to compare.\n\n## What it looks like when it goes wrong\n\nTaking the \"top\" items after sorting actually gives the lowest ones.\n\n## How to spot it\n\nCheck whether `reverse=True` is needed for what you actually want.\n\n## How to fix it\n\nAdd `reverse=True` for descending order.\n\n## Try it\n\n```python run\nscores = [10, 30, 20]\nprint(sorted(scores, reverse=True))\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (75, 'exception-handling', 'Exception handling', 'A bare except: hides every error, including genuine bugs.', '## What it is\n\n`try`/`except` lets you handle specific, expected errors gracefully - but a bare `except:` catches everything, including mistakes you never intended to handle.\n\n## What it looks like when it goes wrong\n\nA function silently returns the wrong thing (often `None`) instead of crashing where the real mistake is.\n\n## How to spot it\n\nLook for bare `except:` clauses, especially around code that otherwise looks correct.\n\n## How to fix it\n\nCatch only the specific exception types you expect.\n\n## Try it\n\n```python run\ntry:\n    result = 10 / 0\nexcept ZeroDivisionError:\n    print(\"Can\'t divide by zero\")\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (76, 'identity-vs-equality', 'is vs ==', '== compares values; is compares identity (the exact same object).', '## What it is\n\n`==` asks \"do these have the same value?\". `is` asks \"are these the exact same object in memory?\".\n\n## What it looks like when it goes wrong\n\nTwo lists (or other objects) with identical contents compare as not equal when checked with `is`.\n\n## How to spot it\n\nCheck whether `is` is being used where a value comparison (`==`) was actually meant.\n\n## How to fix it\n\nUse `==` for value comparisons; reserve `is` for `None` checks or genuine identity checks.\n\n## Try it\n\n```python run\na = [1, 2, 3]\nb = [1, 2, 3]\nprint(a == b)\nprint(a is b)\n```', '2026-11-21 16:47:42');
INSERT INTO `bh_concepts` VALUES (77, 'reading-tracebacks', 'Reading tracebacks', 'Start at the last line and work up - that names the error and shows where it happened.', '## What it is\n\nA traceback is Python\'s full error report: the exception type and message at the bottom, and the chain of calls that led there above it, in the order Python followed them.\n\n## What it looks like when it goes wrong\n\n```\nTraceback (most recent call last):\n  File \"<student>\", line 2, in <module>\n    print(divide(10, 0))\n  File \"<student>\", line 1, in divide\n    return a / b\nZeroDivisionError: division by zero\n```\n\n## How to spot it\n\nStart at the very last line - that names the exception and the message. Then look at the line just above it, which shows where in your code it actually happened. Lines further up show how execution got there (useful for recursion or nested calls), but the bottom two lines are where to look first.\n\n## How to fix it\n\nUse the exception type and message to work out what went wrong, then fix the line the traceback points to - not just the first line of the program.\n\n## Try it\n\n```python run\ndef divide(a, b):\n    return a / b\n\nprint(divide(10, 0))\n```', '2026-11-22 09:29:47');
INSERT INTO `bh_hints` VALUES (166, 56, 1, 'This code won\'t even run yet - look at the error message before you think about logic at all.');
INSERT INTO `bh_hints` VALUES (167, 56, 2, 'Look closely at the `def` line. Every line that opens a block needs something specific at the end.');
INSERT INTO `bh_hints` VALUES (168, 56, 3, 'Add a colon `:` at the end of the `def is_even(n)` line.');
INSERT INTO `bh_hints` VALUES (169, 57, 1, 'This won\'t run at all - read the error message, it tells you exactly what Python was still waiting for.');
INSERT INTO `bh_hints` VALUES (170, 57, 2, 'Count the opening and closing parentheses on the `print` line.');
INSERT INTO `bh_hints` VALUES (171, 57, 3, 'Add the missing `)` at the end of the `print(...)` line.');
INSERT INTO `bh_hints` VALUES (172, 58, 1, 'Read the error carefully - it names the exact kind of punctuation problem this is.');
INSERT INTO `bh_hints` VALUES (173, 58, 2, 'Look at the quote marks around the text. Do they come in a matching pair?');
INSERT INTO `bh_hints` VALUES (174, 58, 3, 'Add the missing closing `\"` right after \"Level complete!\".');
INSERT INTO `bh_hints` VALUES (175, 59, 1, 'This is an `IndentationError` - Python expected something it didn\'t find. Read exactly what it says.');
INSERT INTO `bh_hints` VALUES (176, 59, 2, 'Compare the `return` line to the `def` line above it. Where does Python expect the body of a function to sit?');
INSERT INTO `bh_hints` VALUES (177, 59, 3, 'Indent the `return` line by 4 spaces so it sits inside the function.');
INSERT INTO `bh_hints` VALUES (178, 60, 1, 'Read the error type carefully - it names a specific mix-up in how the whitespace is written, not just \"wrong amount\".');
INSERT INTO `bh_hints` VALUES (179, 60, 2, 'Line 3 is indented differently to its neighbours, even though it looks about right on screen.');
INSERT INTO `bh_hints` VALUES (180, 60, 3, 'Replace the tab character at the start of line 3 with spaces, matching the rest of the file.');
INSERT INTO `bh_hints` VALUES (181, 61, 1, 'This crashes with a `NameError` - Python has no idea what this name refers to.');
INSERT INTO `bh_hints` VALUES (182, 61, 2, 'There\'s a built-in function that does exactly this. Check its spelling very carefully, letter by letter.');
INSERT INTO `bh_hints` VALUES (183, 61, 3, 'Change `Print` to `print` (lowercase).');
INSERT INTO `bh_hints` VALUES (184, 62, 1, 'This is a syntax error about assignment - something is being used in a place Python only allows a comparison.');
INSERT INTO `bh_hints` VALUES (185, 62, 2, 'Look inside the `if` condition. There are two different symbols that both involve equals signs - which one compares values?');
INSERT INTO `bh_hints` VALUES (186, 62, 3, 'Change `=` to `==` inside the `if` condition.');
INSERT INTO `bh_hints` VALUES (187, 63, 1, 'This won\'t run - Python doesn\'t recognise one of the keywords used here.');
INSERT INTO `bh_hints` VALUES (188, 63, 2, 'Python\'s \"else if\" keyword is a single word, and it isn\'t spelled the way some other languages spell it.');
INSERT INTO `bh_hints` VALUES (189, 63, 3, 'Change `elseif` to `elif`.');
INSERT INTO `bh_hints` VALUES (190, 64, 1, 'This crashes with a `TypeError` about something not being subscriptable - a clue about which bracket is wrong.');
INSERT INTO `bh_hints` VALUES (191, 64, 2, 'Calling a method (like `.upper`) and indexing into something use different brackets. Which one is this?');
INSERT INTO `bh_hints` VALUES (192, 64, 3, 'Change `word.upper[]` to `word.upper()`.');
INSERT INTO `bh_hints` VALUES (193, 65, 1, 'This is a syntax error on the `def` line itself.');
INSERT INTO `bh_hints` VALUES (194, 65, 2, 'Every function definition needs its parameters wrapped in a specific kind of bracket.');
INSERT INTO `bh_hints` VALUES (195, 65, 3, 'Wrap `n` in parentheses: `def square(n):`.');
INSERT INTO `bh_hints` VALUES (196, 66, 1, 'The code runs and then crashes - that\'s a `NameError`. Read the traceback\'s last line first.');
INSERT INTO `bh_hints` VALUES (197, 66, 2, 'Look at the variable used inside the message. Compare its spelling to the function\'s parameter.');
INSERT INTO `bh_hints` VALUES (198, 66, 3, '`nmae` should be `name` - fix the typo so it matches the parameter exactly.');
INSERT INTO `bh_hints` VALUES (199, 67, 1, 'This crashes with a `TypeError` about joining two things together.');
INSERT INTO `bh_hints` VALUES (200, 67, 2, '`age` is a number, but `+` between a string and a number is not allowed directly.');
INSERT INTO `bh_hints` VALUES (201, 67, 3, 'Wrap `age` in `str(...)` before joining it to the string.');
INSERT INTO `bh_hints` VALUES (202, 68, 1, 'This crashes with an `IndexError` - the position asked for is out of range.');
INSERT INTO `bh_hints` VALUES (203, 68, 2, 'If a list has 3 items, what are its valid index positions? Does `len(items)` itself point at a real item?');
INSERT INTO `bh_hints` VALUES (204, 68, 3, 'Use `items[len(items) - 1]` instead of `items[len(items)]`.');
INSERT INTO `bh_hints` VALUES (205, 69, 1, 'This crashes with a `KeyError` - the dictionary was asked for something it doesn\'t have.');
INSERT INTO `bh_hints` VALUES (206, 69, 2, 'There\'s a dictionary method that returns a default value instead of crashing when a key is missing.');
INSERT INTO `bh_hints` VALUES (207, 69, 3, 'Use `colours.get(fruit, \"unknown\")` instead of `colours[fruit]`.');
INSERT INTO `bh_hints` VALUES (208, 70, 1, 'This crashes with a `ZeroDivisionError` on at least one test - which input might make `len(nums)` zero?');
INSERT INTO `bh_hints` VALUES (209, 70, 2, 'Check for an empty list before dividing, and decide what the function should return in that case.');
INSERT INTO `bh_hints` VALUES (210, 70, 3, 'Add `if len(nums) == 0: return 0` before the division.');
INSERT INTO `bh_hints` VALUES (211, 71, 1, 'This crashes with a `ValueError` on at least one test - the text given isn\'t in the exact shape `int()` accepts.');
INSERT INTO `bh_hints` VALUES (212, 71, 2, '`int()` can convert whole-number text directly, but not text with a decimal point. What can read a decimal point first?');
INSERT INTO `bh_hints` VALUES (213, 71, 3, 'Convert via `float(text)` first, then wrap that in `int(...)`.');
INSERT INTO `bh_hints` VALUES (214, 72, 1, 'The code runs without errors, but the result is always `None` - that\'s a strong clue about what\'s missing.');
INSERT INTO `bh_hints` VALUES (215, 72, 2, 'A function only gives back a value if it explicitly says to.');
INSERT INTO `bh_hints` VALUES (216, 72, 3, 'Add `return total` as the last line of the function.');
INSERT INTO `bh_hints` VALUES (217, 73, 1, 'This crashes with an `UnboundLocalError` - a variable is used before it has a value, inside this function specifically.');
INSERT INTO `bh_hints` VALUES (218, 73, 2, 'Assigning to a name anywhere inside a function makes Python treat it as local for the *whole* function, even on lines before the assignment. Is `count` meant to be local here?');
INSERT INTO `bh_hints` VALUES (219, 73, 3, 'Add `global count` as the first line inside `increment`.');
INSERT INTO `bh_hints` VALUES (220, 74, 1, 'This crashes with a `TypeError` about joining a string and a number.');
INSERT INTO `bh_hints` VALUES (221, 74, 2, '`price_text` looks like a number but is still text - what does `\"4\" * 3` actually produce?');
INSERT INTO `bh_hints` VALUES (222, 74, 3, 'Convert `price_text` with `int(...)` before using it in the calculation.');
INSERT INTO `bh_hints` VALUES (223, 75, 1, 'This crashes with a `TypeError` about the number of arguments given versus expected.');
INSERT INTO `bh_hints` VALUES (224, 75, 2, 'Compare the function\'s `def` line to what the brief says it should accept.');
INSERT INTO `bh_hints` VALUES (225, 75, 3, 'Add the missing `last_name` parameter and use it in the greeting.');
INSERT INTO `bh_hints` VALUES (226, 76, 1, 'The code runs without errors, so this is a logic bug. Compare your result for `sum_to(4)` with 10.');
INSERT INTO `bh_hints` VALUES (227, 76, 2, 'Look at the `range()` call. Which numbers does `range(1, n)` actually produce?');
INSERT INTO `bh_hints` VALUES (228, 76, 3, '`range` stops one short of its second value. You need the loop to reach `n` itself.');
INSERT INTO `bh_hints` VALUES (229, 77, 1, 'This runs fine but gives the wrong number - count the posts for a tiny fence by hand (try 1 section) and compare.');
INSERT INTO `bh_hints` VALUES (230, 77, 2, 'A fence with 1 section has posts at both ends - that\'s 2 posts, not 1.');
INSERT INTO `bh_hints` VALUES (231, 77, 3, 'Add 1 to `sections`.');
INSERT INTO `bh_hints` VALUES (232, 78, 1, 'This passes some tests but not others - try an example where the exact average has a fraction in it.');
INSERT INTO `bh_hints` VALUES (233, 78, 2, 'There are two different division operators in Python, and they behave very differently.');
INSERT INTO `bh_hints` VALUES (234, 78, 3, 'Change `//` to `/`.');
INSERT INTO `bh_hints` VALUES (235, 79, 1, 'This runs fine but gives the wrong answer for most inputs - check `average_two(4, 6)` by hand.');
INSERT INTO `bh_hints` VALUES (236, 79, 2, 'Without brackets, which happens first: the division, or the addition?');
INSERT INTO `bh_hints` VALUES (237, 79, 3, 'Wrap `a + b` in brackets so it happens before the division: `(a + b) / 2`.');
INSERT INTO `bh_hints` VALUES (238, 80, 1, 'Try a name that\'s clearly too long or too short - does it get rejected like you\'d expect?');
INSERT INTO `bh_hints` VALUES (239, 80, 2, 'Both conditions need to be true for a name to be valid - is that what `or` checks?');
INSERT INTO `bh_hints` VALUES (240, 80, 3, 'Change `or` to `and`.');
INSERT INTO `bh_hints` VALUES (241, 81, 1, 'This works when the first number happens to be even, but fails otherwise - try a list that starts with an odd number.');
INSERT INTO `bh_hints` VALUES (242, 81, 2, 'Look at the indentation of the final `return None`. Is it meant to run after checking just one number, or after checking all of them?');
INSERT INTO `bh_hints` VALUES (243, 81, 3, 'Move `return None` outside the `for` loop, so it only runs once every number has been checked.');
INSERT INTO `bh_hints` VALUES (244, 82, 1, 'The first result is right but later ones creep upward - the totals seem to be adding onto each other.');
INSERT INTO `bh_hints` VALUES (245, 82, 2, 'Where is `total` set back to 0? Does that happen once, or once per inner list?');
INSERT INTO `bh_hints` VALUES (246, 82, 3, 'Move `total = 0` inside the outer `for` loop, so it resets for every inner list.');
INSERT INTO `bh_hints` VALUES (247, 83, 1, 'This run gets stopped for taking too long - something about the loop condition never changes.');
INSERT INTO `bh_hints` VALUES (248, 83, 2, 'The `while` loop keeps checking `n > 0`. Does anything inside the loop ever change `n`?');
INSERT INTO `bh_hints` VALUES (249, 83, 3, 'Add `n -= 1` inside the loop body.');
INSERT INTO `bh_hints` VALUES (250, 84, 1, 'This gives the wrong answer for some inputs - try comparing \"10\" and \"9\" and see which one it picks.');
INSERT INTO `bh_hints` VALUES (251, 84, 2, 'The arguments are text, not numbers. How does Python compare two pieces of text?');
INSERT INTO `bh_hints` VALUES (252, 84, 3, 'Convert `a` and `b` to numbers with `int(...)` before comparing them.');
INSERT INTO `bh_hints` VALUES (253, 85, 1, 'This crashes with a `TypeError` saying something is \"not callable\".');
INSERT INTO `bh_hints` VALUES (254, 85, 2, 'There\'s a built-in function called `sum`. Is there also a variable called `sum` in this function?');
INSERT INTO `bh_hints` VALUES (255, 85, 3, 'Remove the unused `sum = 0` line so `sum(...)` still refers to the built-in function.');
INSERT INTO `bh_hints` VALUES (256, 86, 1, 'Try a list with two negative numbers next to each other - does it remove both?');
INSERT INTO `bh_hints` VALUES (257, 86, 2, 'Removing an item from a list while you\'re iterating over it shifts everything after it along by one - which can make the loop skip the very next item.');
INSERT INTO `bh_hints` VALUES (258, 86, 3, 'Build a new list with a list comprehension instead of removing items from the original while looping over it.');
INSERT INTO `bh_hints` VALUES (259, 87, 1, 'This works for lowercase text, but try an all-uppercase word.');
INSERT INTO `bh_hints` VALUES (260, 87, 2, '`\"aeiou\"` only contains lowercase letters. What happens when `ch` is uppercase?');
INSERT INTO `bh_hints` VALUES (261, 87, 3, 'Compare `ch.lower()` against `\"aeiou\"` instead of `ch` directly.');
INSERT INTO `bh_hints` VALUES (262, 88, 1, 'This one crashes with a `RecursionError` - the function keeps calling itself and never stops.');
INSERT INTO `bh_hints` VALUES (263, 88, 2, 'Every recursive function needs a condition where it stops calling itself. Does this one have one?');
INSERT INTO `bh_hints` VALUES (264, 88, 3, 'Add a base case: if `n <= 1`, return `1` directly, before the recursive call.');
INSERT INTO `bh_hints` VALUES (265, 89, 1, 'This runs without errors, but the second line printed isn\'t what you\'d expect from \"start fresh each time\".');
INSERT INTO `bh_hints` VALUES (266, 89, 2, 'A default argument value is created only once, when the function is defined - not fresh on every call. What kind of default value could that cause problems for?');
INSERT INTO `bh_hints` VALUES (267, 89, 3, 'Use `basket=None` as the default, then create a new empty list inside the function if `basket is None`.');
INSERT INTO `bh_hints` VALUES (268, 90, 1, 'This runs fine, but check both printed lines - is the first one what you expected?');
INSERT INTO `bh_hints` VALUES (269, 90, 2, '`doubled = original` doesn\'t make a new list - it makes `doubled` another name for the exact same list.');
INSERT INTO `bh_hints` VALUES (270, 90, 3, 'Use `original.copy()` (or `list(original)`) to make a genuinely separate list.');
INSERT INTO `bh_hints` VALUES (271, 91, 1, 'Only one cell was changed in the code - but look at how many `1`s show up in the output.');
INSERT INTO `bh_hints` VALUES (272, 91, 2, '`[[0] * 3] * 3` repeats the *same inner list* three times, not three independent lists.');
INSERT INTO `bh_hints` VALUES (273, 91, 3, 'Use a list comprehension - `[[0] * 3 for _ in range(3)]` - to create three genuinely separate rows.');
INSERT INTO `bh_hints` VALUES (274, 92, 1, 'At least one test gets stopped for taking too long - the search bounds aren\'t narrowing down the way they should.');
INSERT INTO `bh_hints` VALUES (275, 92, 2, 'When the target is smaller or larger than the middle item, how much does `low` or `high` actually move? Could `mid` ever equal `low` or `high` again on the next pass?');
INSERT INTO `bh_hints` VALUES (276, 92, 3, 'Narrow the bounds past `mid`, not onto it: use `low = mid + 1` and `high = mid - 1`.');
INSERT INTO `bh_hints` VALUES (277, 93, 1, 'All three results come out the same - but they were created with three different values of `i`.');
INSERT INTO `bh_hints` VALUES (278, 93, 2, 'A lambda looks up `i` in its enclosing scope *when it\'s called*, not when it\'s created - and there\'s only one `i` variable, shared by the whole loop.');
INSERT INTO `bh_hints` VALUES (279, 93, 3, 'Give the lambda its own parameter with a default: `lambda i=i: i`, capturing the current value at creation time.');
INSERT INTO `bh_hints` VALUES (280, 94, 1, 'The second line printed is lower than the first - but a *high* score should never go down.');
INSERT INTO `bh_hints` VALUES (281, 94, 2, '`local_high` is a brand new local variable every call - does it actually update `high_score` for next time?');
INSERT INTO `bh_hints` VALUES (282, 94, 3, 'Declare `global high_score` inside the function, and update `high_score` directly instead of a local copy.');
INSERT INTO `bh_hints` VALUES (283, 95, 1, 'The second printed line is empty - but nothing was removed from `evens` on purpose.');
INSERT INTO `bh_hints` VALUES (284, 95, 2, 'A generator expression `(... for ...)` only produces its values once, in one pass. What happens once every value has been read?');
INSERT INTO `bh_hints` VALUES (285, 95, 3, 'Return a list comprehension `[...]` instead of a generator expression `(...)`, so it can be listed more than once.');
INSERT INTO `bh_hints` VALUES (286, 96, 1, 'The first test fails even though `0.7 + 0.2 + 0.1` really does equal 1 on paper.');
INSERT INTO `bh_hints` VALUES (287, 96, 2, 'Computers store decimal fractions like `0.1` approximately, in binary - try printing `0.7 + 0.2 + 0.1` directly and look closely at the result.');
INSERT INTO `bh_hints` VALUES (288, 96, 3, 'Use `math.isclose(a + b + c, 1.0)` instead of `==`.');
INSERT INTO `bh_hints` VALUES (289, 97, 1, 'This crashes with a `RuntimeError` about the dictionary changing size.');
INSERT INTO `bh_hints` VALUES (290, 97, 2, 'Python won\'t let you add or remove keys from a dictionary while you\'re directly looping over it. Can you loop over something else instead - a snapshot of the keys, perhaps?');
INSERT INTO `bh_hints` VALUES (291, 97, 3, 'Loop over `list(stock.keys())` instead of `stock` directly.');
INSERT INTO `bh_hints` VALUES (292, 98, 1, 'This returns the 3 *lowest* scorers instead of the 3 highest.');
INSERT INTO `bh_hints` VALUES (293, 98, 2, '`sorted()` arranges things smallest-to-largest by default. Does taking the first 3 of that give you the top, or the bottom?');
INSERT INTO `bh_hints` VALUES (294, 98, 3, 'Add `reverse=True` to `sorted(...)` so it goes largest-to-smallest.');
INSERT INTO `bh_hints` VALUES (295, 99, 1, 'This never crashes, but it also never seems to return the right answer - it just gives back `None` every time.');
INSERT INTO `bh_hints` VALUES (296, 99, 2, 'A bare `except:` catches *every* kind of error, including ones caused by ordinary typos elsewhere in the same `try` block. Is there a typo hiding in there?');
INSERT INTO `bh_hints` VALUES (297, 99, 3, 'There\'s a spelling mistake (`resutl` vs `result`) causing a `NameError` that the bare `except` is silently swallowing. Fix the typo, and prefer not catching errors you don\'t expect.');
INSERT INTO `bh_hints` VALUES (298, 100, 1, 'Two lists that clearly contain the same values still come back `False` - think about what\'s actually being checked.');
INSERT INTO `bh_hints` VALUES (299, 100, 2, '`is` checks whether two names point at the *exact same object* in memory, not whether their contents match.');
INSERT INTO `bh_hints` VALUES (300, 100, 3, 'Use `==` instead of `is` to compare contents.');
INSERT INTO `bh_hints` VALUES (301, 101, 1, 'Try scores that land exactly on 50 or 70, and try an empty list - does the brief\'s boundary wording match what the code actually does?');
INSERT INTO `bh_hints` VALUES (302, 101, 2, 'There are two separate problems here: what happens with no scores at all, and what happens exactly on a grade boundary.');
INSERT INTO `bh_hints` VALUES (303, 101, 3, 'Guard against an empty list before dividing, and use `>=` instead of `>` so a score exactly on the boundary gets the higher grade.');
INSERT INTO `bh_hints` VALUES (304, 102, 1, 'Simple shifts work, but try shifting a letter near the end of the alphabet, and try text with spaces or punctuation in it.');
INSERT INTO `bh_hints` VALUES (305, 102, 2, 'There are two separate problems: what happens when the shift goes past \'z\', and what happens to characters that aren\'t letters at all.');
INSERT INTO `bh_hints` VALUES (306, 102, 3, 'Use the alphabet position (`ord(ch) - ord(\'a\')`), apply `% 26` to wrap around, then add `ord(\'a\')` back - and leave non-letters untouched with an `else` branch.');
INSERT INTO `bh_hints` VALUES (307, 103, 1, 'Row and column wins work, but try a board where only a diagonal has three in a row, and try a completely full board with no winner.');
INSERT INTO `bh_hints` VALUES (308, 103, 2, 'How many different ways can three-in-a-row happen on this board? Rows and columns are checked - is that the complete list?');
INSERT INTO `bh_hints` VALUES (309, 103, 3, 'Add checks for both diagonals, and after checking every line, check whether the board is completely full to detect a draw.');
INSERT INTO `bh_hints` VALUES (310, 104, 1, 'Withdraw from one account, then check the *other* account\'s transaction list - should it really have changed?');
INSERT INTO `bh_hints` VALUES (311, 104, 2, '`transactions = []` is defined directly under `class Account:`, not inside `__init__`. What\'s the difference between a class attribute and an instance attribute?');
INSERT INTO `bh_hints` VALUES (312, 104, 3, 'Move `transactions = []` inside `__init__` as `self.transactions = []`, and add a balance check inside `withdraw` before subtracting.');
INSERT INTO `bh_hints` VALUES (313, 105, 1, 'Place one order for 3 apples when there are 10 - how many are left afterwards? Also try ordering something that isn\'t in stock at all.');
INSERT INTO `bh_hints` VALUES (314, 105, 2, 'Look very closely at the two lines that update `stock[item]` - are they actually different from each other?');
INSERT INTO `bh_hints` VALUES (315, 105, 3, 'Remove the duplicate `stock[item] -= qty` line, and add a check to skip (or `continue`) when `item` isn\'t in `stock`.');
INSERT INTO `bh_hints` VALUES (316, 106, 1, 'Try `primes_up_to(2)` specifically - 2 is prime, so should it be included? Also check whether `1` ever shows up in a result list.');
INSERT INTO `bh_hints` VALUES (317, 106, 2, 'The list is sized `n`, and the loop runs `range(2, n)` - does either of those actually reach `n` itself? Also, is `1` ever explicitly marked as not prime?');
INSERT INTO `bh_hints` VALUES (318, 106, 3, 'Size the list `n + 1` and loop up to `n + 1` so `n` itself is included, and explicitly set `is_prime[1] = False` as well as `is_prime[0]`.');
INSERT INTO `bh_hints` VALUES (319, 107, 1, 'Try a list that\'s already partly or fully sorted descending - does the result come out the right *length*?');
INSERT INTO `bh_hints` VALUES (320, 107, 2, 'The main merging loop stops as soon as *either* `left` or `right` runs out - but what about whatever is left over in the other one?');
INSERT INTO `bh_hints` VALUES (321, 107, 3, 'After the `while` loop, add the leftover tail of each half: `merged.extend(left[i:])` and `merged.extend(right[j:])`.');
INSERT INTO `bh_hints` VALUES (322, 108, 1, 'With more than one item, the result only ever has one item in it, no matter how long the input list was.');
INSERT INTO `bh_hints` VALUES (323, 108, 2, 'Inside the loop, `current.next` is changed *before* it\'s used to move `current` forward. What does `current.next` point to by the time that line runs?');
INSERT INTO `bh_hints` VALUES (324, 108, 3, 'Save `current.next` in a temporary variable *before* overwriting it, then use that saved value to advance `current`.');
INSERT INTO `bh_hints` VALUES (325, 109, 1, 'Try text with punctuation stuck to a word, and also try an empty string - one of these crashes, the other just gives a misleading number.');
INSERT INTO `bh_hints` VALUES (326, 109, 2, 'Does `\"world!\"` count as 6 characters long, or 5? And what does `len(words)` equal for an empty string, once split?');
INSERT INTO `bh_hints` VALUES (327, 109, 3, 'Strip punctuation off each word before measuring its length, and return early with zeros when there are no words at all.');
INSERT INTO `bh_hints` VALUES (328, 110, 1, 'Try a simple case by hand: ┬ú30 total with a 10% discount should come to ┬ú27. Does it?');
INSERT INTO `bh_hints` VALUES (329, 110, 2, 'A percentage discount should be the total *multiplied by* the percentage, not the total *minus* the raw percentage number.');
INSERT INTO `bh_hints` VALUES (330, 110, 3, 'Change `discount = total - discount_percent / 100` to `discount = total * (discount_percent / 100)`.');
