INSERT INTO `bh_puzzle_bugs` VALUES (63, 56, 1, 1, 1, 'syntax', 41, 'The `def` line has no colon, so Python can\'t tell where the function\'s body is supposed to start.', 'Add `:` after the closing parenthesis: `def is_even(n):`.');
INSERT INTO `bh_puzzle_bugs` VALUES (64, 57, 1, 2, 2, 'syntax', 39, 'The `print(` call is never closed with a matching `)`.', 'Add `)` at the end of the line.');
INSERT INTO `bh_puzzle_bugs` VALUES (65, 58, 1, 1, 1, 'syntax', 40, 'The string is opened with `\"` but never closed, so Python keeps reading past the end of the line looking for the matching quote.', 'Add the missing closing `\"` before the final `)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (66, 59, 1, 2, 2, 'syntax', 42, 'The function body isn\'t indented, so Python doesn\'t recognise it as belonging to `double`.', 'Indent line 2 by 4 spaces.');
INSERT INTO `bh_puzzle_bugs` VALUES (67, 60, 1, 3, 4, 'syntax', 42, 'Line 3 is indented with a tab while line 4 (meant to be at the same level) uses spaces - Python can\'t be sure they line up.', 'Re-indent both lines using spaces only.');
INSERT INTO `bh_puzzle_bugs` VALUES (68, 61, 1, 2, 2, 'runtime', 43, 'Python is case-sensitive, so `Print` is a completely different, undefined name from the built-in `print`.', 'Use lowercase `print`.');
INSERT INTO `bh_puzzle_bugs` VALUES (69, 62, 1, 2, 2, 'syntax', 44, '`=` assigns a value; `==` compares two values. An `if` condition needs a comparison.', 'Change `if x = 5:` to `if x == 5:`.');
INSERT INTO `bh_puzzle_bugs` VALUES (70, 63, 1, 4, 4, 'syntax', 45, '`elseif` isn\'t a Python keyword - Python\'s word for this is `elif`.', 'Change `elseif` to `elif`.');
INSERT INTO `bh_puzzle_bugs` VALUES (71, 64, 1, 2, 2, 'runtime', 46, 'Square brackets `[]` are for indexing; round brackets `()` call a function or method. `.upper` is a method, so it needs `()`.', 'Change `[]` to `()`.');
INSERT INTO `bh_puzzle_bugs` VALUES (72, 65, 1, 1, 1, 'syntax', 47, 'The function\'s parameters need to be inside parentheses - `def square n:` is missing them.', 'Change `def square n:` to `def square(n):`.');
INSERT INTO `bh_puzzle_bugs` VALUES (73, 66, 1, 2, 2, 'runtime', 48, '`nmae` is never defined - it\'s a typo for the parameter `name`, so Python raises a `NameError` the moment this line runs.', 'Change `nmae` to `name`.');
INSERT INTO `bh_puzzle_bugs` VALUES (74, 67, 1, 2, 2, 'runtime', 49, '`+` between a string and an `int` is not allowed - `age` needs converting to a string first.', 'Use `str(age)` instead of `age`.');
INSERT INTO `bh_puzzle_bugs` VALUES (75, 68, 1, 2, 2, 'runtime', 50, 'Valid indexes run from `0` to `len(items) - 1`. `items[len(items)]` is one position past the last real item.', 'Subtract 1: `items[len(items) - 1]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (76, 69, 1, 3, 3, 'runtime', 51, '`colours[fruit]` crashes if `fruit` isn\'t a key already in the dictionary.', 'Use `.get(fruit, \"unknown\")` to supply a default instead of crashing.');
INSERT INTO `bh_puzzle_bugs` VALUES (77, 70, 1, 2, 2, 'runtime', 52, 'If `nums` is empty, `len(nums)` is `0` and the division crashes.', 'Guard against an empty list before dividing.');
INSERT INTO `bh_puzzle_bugs` VALUES (78, 71, 1, 2, 2, 'runtime', 49, '`int(\"3.5\")` crashes - `int()` only accepts text that looks like a whole number.', 'Convert with `int(float(text))` so a decimal point is handled first.');
INSERT INTO `bh_puzzle_bugs` VALUES (79, 72, 1, 2, 2, 'runtime', 54, 'The function computes `total` but never returns it, so it implicitly returns `None`.', 'Add `return total`.');
INSERT INTO `bh_puzzle_bugs` VALUES (80, 73, 1, 4, 4, 'runtime', 48, 'Assigning to `count` inside the function makes Python treat it as a local variable throughout the function - including on the right-hand side, before it\'s been given a local value.', 'Add `global count` before using it.');
INSERT INTO `bh_puzzle_bugs` VALUES (81, 74, 1, 2, 2, 'runtime', 49, '`price_text` is a string, so `price_text * quantity` repeats the text rather than multiplying a number, and adding `5` to that then crashes.', 'Convert with `int(price_text)` first.');
INSERT INTO `bh_puzzle_bugs` VALUES (82, 75, 1, 1, 2, 'runtime', 55, 'The function only accepts one parameter, but the brief (and the tests) need two.', 'Add `last_name` as a second parameter and include it in the returned greeting.');
INSERT INTO `bh_puzzle_bugs` VALUES (83, 76, 1, 3, 3, 'logic', 56, '`range(1, n)` stops at `n - 1`, so `n` is never added.', 'Use `range(1, n + 1)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (84, 77, 1, 2, 2, 'logic', 56, 'The number of posts is always one more than the number of sections (there\'s a post at both ends), but this just returns the section count.', 'Return `sections + 1`.');
INSERT INTO `bh_puzzle_bugs` VALUES (85, 78, 1, 2, 2, 'logic', 58, '`//` throws away the remainder (integer division); the brief needs the exact average, including any fraction.', 'Use `/` instead of `//`.');
INSERT INTO `bh_puzzle_bugs` VALUES (86, 79, 1, 2, 2, 'logic', 59, 'Without brackets, `/` happens before `+`, so this divides only `b` by 2 instead of the whole sum.', 'Add brackets: `(a + b) / 2`.');
INSERT INTO `bh_puzzle_bugs` VALUES (87, 80, 1, 2, 2, 'logic', 60, 'With `or`, almost every length passes (anything satisfies at least one side). Both conditions need to hold at once.', 'Change `or` to `and`.');
INSERT INTO `bh_puzzle_bugs` VALUES (88, 81, 1, 5, 5, 'logic', 61, '`return None` is inside the loop, so it runs on the very first number if that one isn\'t even - the loop never gets a chance to check the rest.', 'Dedent `return None` so it\'s after the loop, not inside it.');
INSERT INTO `bh_puzzle_bugs` VALUES (89, 82, 1, 2, 2, 'logic', 62, '`total` is only reset to 0 once, before the outer loop starts, so each inner list\'s sum keeps adding onto the previous one.', 'Move `total = 0` inside the outer loop, right before the inner loop.');
INSERT INTO `bh_puzzle_bugs` VALUES (90, 83, 1, 4, 4, 'logic', 63, '`n` is never decreased, so `n > 0` stays true forever and the loop never ends.', 'Add `n -= 1` after `result.append(n)`.');
INSERT INTO `bh_puzzle_bugs` VALUES (91, 84, 1, 2, 2, 'logic', 49, '`a` and `b` are strings, so `a > b` compares them alphabetically (like a dictionary), not numerically - `\"9\"` sorts after `\"10\"`.', 'Convert both to `int` before comparing.');
INSERT INTO `bh_puzzle_bugs` VALUES (92, 85, 1, 2, 2, 'runtime', 64, 'Naming a variable `sum` hides the built-in `sum()` function for the rest of this scope, so `sum(unique)` later tries to call the number `0` instead.', 'Remove the `sum = 0` line - it\'s unused, and it shadows the builtin needed later.');
INSERT INTO `bh_puzzle_bugs` VALUES (93, 86, 1, 2, 4, 'logic', 65, 'Removing items from `nums` while looping over it shifts the remaining items\' positions, so the loop can skip the item right after a removed one.', 'Build a new filtered list instead, e.g. with a list comprehension.');
INSERT INTO `bh_puzzle_bugs` VALUES (94, 87, 1, 4, 4, 'logic', 66, '`\"aeiou\"` only matches lowercase vowels, so uppercase ones like `\'A\'` are never counted.', 'Use `ch.lower() in \"aeiou\"`.');
INSERT INTO `bh_puzzle_bugs` VALUES (95, 88, 1, 1, 2, 'runtime', 69, 'There\'s no base case, so `factorial` keeps calling itself with a smaller `n` forever, until Python\'s recursion limit is hit.', 'Add `if n <= 1: return 1` before the recursive call.');
INSERT INTO `bh_puzzle_bugs` VALUES (96, 89, 1, 1, 1, 'logic', 67, 'The default list `[]` is created once when the function is defined, and reused across every call that doesn\'t supply its own basket - so items pile up across calls instead of starting fresh.', 'Default to `None`, and create a new list inside the function when no basket is given.');
INSERT INTO `bh_puzzle_bugs` VALUES (97, 90, 1, 2, 2, 'logic', 68, '`doubled = original` makes `doubled` point at the same list object as `original`, so changing one through its index changes both.', 'Use `original.copy()` to create an independent list.');
INSERT INTO `bh_puzzle_bugs` VALUES (98, 91, 1, 1, 1, 'logic', 68, '`[[0] * 3] * 3` makes a list containing the *same* inner list object three times, so changing one row through an index changes every row.', 'Build the rows with a list comprehension so each one is a separate list.');
INSERT INTO `bh_puzzle_bugs` VALUES (99, 92, 1, 7, 9, 'logic', 70, 'Setting `low = mid` or `high = mid` (instead of `mid + 1` / `mid - 1`) can leave the search bounds unchanged between passes, looping forever when the target isn\'t present.', 'Move the bounds past `mid`: `low = mid + 1` and `high = mid - 1`, and start `high` at `len(items) - 1`.');
INSERT INTO `bh_puzzle_bugs` VALUES (100, 93, 1, 3, 3, 'logic', 71, 'The lambda doesn\'t capture `i`\'s value at creation time - it looks `i` up when called, by which point the loop has finished and `i` holds its final value for every lambda.', 'Use a default argument to capture the current value: `lambda i=i: i`.');
INSERT INTO `bh_puzzle_bugs` VALUES (101, 94, 1, 4, 4, 'logic', 48, '`local_high` copies `high_score`\'s value but never writes back to it, so the module-level `high_score` stays `0` forever and each call compares against that, not the real running high score.', 'Add `global high_score` and update `high_score` itself.');
INSERT INTO `bh_puzzle_bugs` VALUES (102, 95, 1, 2, 2, 'logic', 72, 'A generator can only be stepped through once - the first `list(evens)` consumes every value, so the second one has nothing left to give.', 'Use a list comprehension `[n for n in nums if ...]` instead, which can be read as many times as needed.');
INSERT INTO `bh_puzzle_bugs` VALUES (103, 96, 1, 2, 2, 'logic', 73, 'Floating-point numbers can\'t represent most decimal fractions exactly, so `0.1 + 0.2 + 0.7` comes out as something like `0.9999999999999999`, not exactly `1.0`.', 'Use `math.isclose(...)` to compare with a small tolerance instead of `==`.');
INSERT INTO `bh_puzzle_bugs` VALUES (104, 97, 1, 2, 2, 'runtime', 65, 'Python detects that the dictionary\'s size changed mid-loop (from `del`) and refuses to continue, since it can no longer guarantee which items have been visited.', 'Loop over a snapshot of the keys instead: `for item in list(stock.keys()):`.');
INSERT INTO `bh_puzzle_bugs` VALUES (105, 98, 1, 2, 2, 'logic', 74, '`sorted()` defaults to ascending order, so taking the first 3 items gives the lowest scorers, not the highest.', 'Add `reverse=True`.');
INSERT INTO `bh_puzzle_bugs` VALUES (106, 99, 1, 3, 6, 'logic', 75, 'A typo (`resutl` instead of `result`) causes a `NameError` every single call, but the bare `except:` catches it silently and returns `None`, hiding the real bug completely.', 'Fix the typo, and avoid bare `except:` clauses that can hide genuine bugs like this one.');
INSERT INTO `bh_puzzle_bugs` VALUES (107, 100, 1, 2, 2, 'logic', 76, '`is` checks object identity (are these literally the same object?), not equal contents - two separately-created lists with identical items are still different objects.', 'Use `==` to compare values instead of `is`.');
INSERT INTO `bh_puzzle_bugs` VALUES (108, 101, 1, 5, 5, 'runtime', 52, 'If `scores` is empty, `len(scores)` is `0` and dividing by it crashes with a `ZeroDivisionError`.', 'Check for an empty list first and return `\"No scores\"` before dividing.');
INSERT INTO `bh_puzzle_bugs` VALUES (109, 101, 2, 6, 9, 'logic', NULL, 'Using `>` instead of `>=` means a score landing exactly on a boundary (70 or 50) is marked down a grade.', 'Change both comparisons to `>=` so the boundary itself counts for the higher grade.');
INSERT INTO `bh_puzzle_bugs` VALUES (110, 102, 1, 4, 4, 'logic', 56, 'Adding `shift` directly to the character code doesn\'t wrap around the alphabet - shifting \'z\' just gives the character after \'z\', not back to \'a\'.', 'Work in alphabet positions 0-25 with `% 26` to wrap around, then convert back to a character.');
INSERT INTO `bh_puzzle_bugs` VALUES (111, 102, 2, 4, 5, 'logic', NULL, 'Every character is shifted, including spaces and punctuation, which should be left exactly as they are.', 'Only shift letters (`ch.isupper()` or `ch.islower()`); copy everything else through unchanged.');
INSERT INTO `bh_puzzle_bugs` VALUES (112, 103, 1, 1, 8, 'logic', NULL, 'Only rows and columns are checked for a win - the two diagonals are never checked at all.', 'Also check `board[0][0], board[1][1], board[2][2]` and `board[0][2], board[1][1], board[2][0]`.');
INSERT INTO `bh_puzzle_bugs` VALUES (113, 103, 2, 8, 8, 'logic', NULL, 'A full board with no winner should return `\"Draw\"`, but this always returns `None` once every line has been checked.', 'After checking every line, check if every cell is filled and return `\"Draw\"` if so.');
INSERT INTO `bh_puzzle_bugs` VALUES (114, 104, 1, 2, 2, 'logic', 67, '`transactions = []` written directly under the class is a *class* attribute, shared by every instance - one account\'s withdrawals show up in every other account\'s transaction list.', 'Move it inside `__init__` as `self.transactions = []` so each account gets its own list.');
INSERT INTO `bh_puzzle_bugs` VALUES (115, 104, 2, 7, 9, 'logic', NULL, '`withdraw` never checks the balance, so an account can be withdrawn into a negative balance with no warning.', 'Raise an error (e.g. `ValueError`) if `amount` is more than `self.balance`.');
INSERT INTO `bh_puzzle_bugs` VALUES (116, 105, 1, 4, 5, 'logic', NULL, '`stock[item] -= qty` is duplicated, so every order is deducted from stock twice.', 'Delete one of the two identical lines.');
INSERT INTO `bh_puzzle_bugs` VALUES (117, 105, 2, 4, 4, 'runtime', 51, 'An order for an item not already in `stock` crashes with a `KeyError` instead of being safely ignored.', 'Check `if item not in stock: continue` before updating it.');
INSERT INTO `bh_puzzle_bugs` VALUES (118, 106, 1, 2, 4, 'logic', 56, 'The list has size `n` and the loops stop before reaching `n`, so `n` itself is never considered - even when it\'s prime.', 'Size the list `n + 1` and loop through `range(2, n + 1)` so `n` is included.');
INSERT INTO `bh_puzzle_bugs` VALUES (119, 106, 2, 3, 3, 'logic', NULL, '`1` is never marked as not-prime (only index `0` is), so it can incorrectly show up in the result for small values of `n`.', 'Also set `is_prime[1] = False`.');
INSERT INTO `bh_puzzle_bugs` VALUES (120, 107, 1, 15, 15, 'logic', NULL, 'The merging loop stops as soon as one side (`left` or `right`) is exhausted, but any remaining items in the *other* side are never added to the result - they\'re silently dropped.', 'After the loop, append the leftover tail of both `left` and `right` to `merged`.');
INSERT INTO `bh_puzzle_bugs` VALUES (121, 108, 1, 10, 12, 'logic', NULL, '`current.next = prev` overwrites the link to the rest of the list *before* `current = current.next` reads it, so after the very first step `current` becomes `prev` and the rest of the original list is lost.', 'Save `next_node = current.next` before overwriting `current.next`, and advance using the saved value.');
INSERT INTO `bh_puzzle_bugs` VALUES (122, 109, 1, 2, 2, 'runtime', 52, 'An empty (or whitespace-only) `text` produces an empty `words` list, and dividing by `len(words)` (which is `0`) crashes.', 'Check for an empty `words` list and return the zero-result early.');
INSERT INTO `bh_puzzle_bugs` VALUES (123, 109, 2, 2, 2, 'logic', NULL, 'Punctuation attached to a word (like the comma in \"Hello,\") is counted as part of its length, inflating `avg_word_length`.', 'Strip punctuation characters off each word (e.g. with `.strip(\'.,!?;:\"\\\'\')`) before measuring its length.');
INSERT INTO `bh_puzzle_bugs` VALUES (124, 110, 1, 3, 3, 'logic', 59, 'The discount amount is computed as `total - discount_percent / 100`, which is nowhere close to \"X% of the total\" - it should be a multiplication, not a subtraction.', 'Compute the discount as `total * (discount_percent / 100)`.');
