INSERT INTO `bh_puzzle_tests` VALUES (173, 56, 1, 'is_even(4)', '(4,)', NULL, NULL, 'returns', 'True', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (174, 56, 2, 'is_even(7)', '(7,)', NULL, NULL, 'returns', 'False', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (175, 56, 3, 'is_even(0)', '(0,)', NULL, NULL, 'returns', 'True', 'exact', 1);
