INSERT INTO `bh_puzzle_tests` VALUES (177, 57, 1, 'prints the score', NULL, NULL, '', 'stdout', '\"Final score: 10\\n\"', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (178, 57, 2, 'prints the score (repeat check)', NULL, NULL, '', 'stdout', '\"Final score: 10\\n\"', 'exact', 1);
INSERT INTO `bh_puzzle_tests` VALUES (179, 58, 1, 'prints the message', NULL, NULL, '', 'stdout', '\"Level complete!\\n\"', 'exact', 0);
