INSERT INTO `bh_puzzle_tests` VALUES (183, 59, 3, 'double(-4)', '(-4,)', NULL, NULL, 'returns', '-8', 'exact', 1);
INSERT INTO `bh_puzzle_tests` VALUES (184, 60, 1, 'classify(5)', '(5,)', NULL, NULL, 'returns', '\"positive\"', 'exact', 0);
