INSERT INTO `bh_puzzle_tests` VALUES (325, 106, 1, 'primes_up_to(10)', '(10,)', NULL, NULL, 'returns', '[2, 3, 5, 7]', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (326, 106, 2, 'primes_up_to(2) - the smallest prime, as an inclusive upper bound', '(2,)', NULL, NULL, 'returns', '[2]', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (327, 106, 3, 'primes_up_to(20)', '(20,)', NULL, NULL, 'returns', '[2, 3, 5, 7, 11, 13, 17, 19]', 'exact', 0);
INSERT INTO `bh_puzzle_tests` VALUES (328, 106, 4, 'primes_up_to(1) - no primes at all', '(1,)', NULL, NULL, 'returns', '[]', 'exact', 1);
INSERT INTO `bh_puzzle_tests` VALUES (329, 107, 1, 'merge_sort([5, 2, 4, 1, 3])', '([5, 2, 4, 1, 3],)', NULL, NULL, 'returns', '[1, 2, 3, 4, 5]', 'exact', 0);
