INSERT INTO `bh_puzzle_tests` VALUES (334, 108, 1, 'reverse_to_list([1, 2, 3, 4])', '([1, 2, 3, 4],)', NULL, NULL, 'returns', '[4, 3, 2, 1]', 'exact', 0);
