INSERT INTO `bh_puzzle_tests` VALUES (340, 109, 4, 'text_stats(\"   \")', '(\'   \',)', NULL, NULL, 'returns', '{\"word_count\": 0, \"avg_word_length\": 0}', 'exact', 1);
INSERT INTO `bh_puzzle_tests` VALUES (341, 110, 1, 'total_cost([10, 20], 10)', '([10, 20], 10)', NULL, NULL, 'returns', '27', 'float_tol', 0);
INSERT INTO `bh_puzzle_tests` VALUES (342, 110, 2, 'total_cost([100], 50)', '([100], 50)', NULL, NULL, 'returns', '50', 'float_tol', 0);
