INSERT INTO `bh_puzzles` VALUES (56, 'colon-needed', 6, 'Colon Needed', 1, 1, NULL, 'syntax', '`is_even(n)` should return `True` if `n` is even, and `False` otherwise.\n\nExample: `is_even(4)` should return `True`. `is_even(7)` should return `False`.', 'def is_even(n)\n    return n % 2 == 0\n', 'def is_even(n):\n    return n % 2 == 0\n', 'function', 'is_even', 'Every block header in Python - `def`, `if`, `for`, `while`, `class`, and the rest - ends with a colon. Without it, Python\'s parser doesn\'t know an indented block is coming next, and it fails before running a single line of your code.', 'Before you run anything, scan every line that should open a block and check it ends in `:`.', NULL, 'published', '186e8fc0c1891932c7ec4b984870c0d63ce405c4b29b0f28075bae0c51fd5553', '2026-11-21 16:49:21', NULL, '2026-11-21 16:47:42', '2026-11-21 16:49:21');
INSERT INTO `bh_puzzles` VALUES (57, 'missing-bracket', 6, 'Missing Bracket', 2, 1, NULL, 'syntax', 'This program should print the final score.\n\nExample output: `Final score: 10`', 'score = 10\nprint(\"Final score:\", score\n', 'score = 10\nprint(\"Final score:\", score)\n', 'script', NULL, 'Every opening bracket - `(`, `[`, `{` - needs a matching closing one. Python keeps reading, looking for that match, until it runs out of file, which is why the error can point somewhere that looks far away from the real mistake.', 'Count brackets in pairs on any line you\'re not sure about. An editor that highlights matching brackets (like this one) makes this easy to check at a glance.', NULL, 'published', '6275f982a653c9a139676f50f1ea85e541e123691e9e385b452148cd7aeed9a2', '2026-11-21 16:47:42', NULL, '2026-11-21 16:47:42', '2026-11-21 16:47:42');
INSERT INTO `bh_puzzles` VALUES (58, 'lonely-quote', 6, 'The Lonely Quote', 3, 1, NULL, 'syntax', 'This program should print a level-complete message.\n\nExample output: `Level complete!`', 'print(\"Level complete!)\n', 'print(\"Level complete!\")\n', 'script', NULL, 'A string needs a quote mark at both ends, matching in type (both `\"` or both `\'`). Miss one and Python treats everything afterwards as still being inside the string.', 'Count quote marks in pairs, the same way you would brackets.', NULL, 'published', 'c02f95389c3c4b0e8efc2f682891c5ce7ab9020435d5bb6254d901638afab8e2', '2026-11-21 16:47:42', NULL, '2026-11-21 16:47:42', '2026-11-21 16:47:42');
INSERT INTO `bh_puzzles` VALUES (59, 'indentation-station', 6, 'Indentation Station', 4, 1, NULL, 'syntax', '`double(n)` should return `n` multiplied by 2.\n\nExample: `double(5)` should return `10`.', 'def double(n):\nreturn n * 2\n', 'def double(n):\n    return n * 2\n', 'function', 'double', 'Python uses indentation, not brackets, to show which lines belong inside a block. A colon-ended line always needs its body indented one level in, consistently.', 'After any line ending in `:`, check the next line is indented - your editor\'s auto-indent usually does this for you, which is exactly why it\'s easy to miss when it doesn\'t.', NULL, 'published', '0efa631340af77346e55b17c28866bae25c440e3020bbbe6fc7154489d2fd71e', '2026-11-21 16:47:42', NULL, '2026-11-21 16:47:42', '2026-11-21 16:47:42');
INSERT INTO `bh_puzzles` VALUES (60, 'mixed-signals', 6, 'Mixed Signals', 5, 2, NULL, 'syntax', '`classify(n)` should return `\"positive\"` if `n` is greater than 0, and `\"non-positive\"` otherwise.\n\nExample: `classify(5)` should return `\"positive\"`.', 'def classify(n):\n    if n > 0:\n	x = \"positive\"\n        return x\n    return \"non-positive\"\n', 'def classify(n):\n    if n > 0:\n        return \"positive\"\n    return \"non-positive\"\n', 'function', 'classify', 'Tabs and spaces can look identical on screen but mean different things to Python\'s parser. Mixing them within the same block is ambiguous enough that Python refuses to guess and raises an error instead.', 'Set your editor to show whitespace characters, or just always use spaces (most Python style guides, and this editor, default to this).', NULL, 'published', 'fea6ef16cca2d8419ba02269d1ab155be29ebab9947318b0986db19a205e6bfc', '2026-11-21 16:47:42', NULL, '2026-11-21 16:47:42', '2026-11-21 16:47:42');
INSERT INTO `bh_puzzles` VALUES (61, 'capital-offence', 6, 'Capital Offence', 6, 1, NULL, 'runtime', 'This program should print a name.\n\nExample output: `Ada`', 'name = \"Ada\"\nPrint(name)\n', 'name = \"Ada\"\nprint(name)\n', 'script', NULL, 'Python treats `Print`, `print` and `PRINT` as three unrelated names. Built-in functions and keywords are always lowercase, so a capital letter here means Python goes looking for a name that was never created.', 'If a `NameError` names something that looks like a familiar built-in, check its capitalisation first.', NULL, 'published', '500f0b10e6b98e5454a109d7680842bdf76d2a6d07535d53632bbd35bdeeca32', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (62, 'single-equals', 6, 'Single Equals', 7, 2, NULL, 'syntax', '`check(x)` should return `\"five\"` if `x` equals 5, and `\"not five\"` otherwise.\n\nExample: `check(5)` should return `\"five\"`.', 'def check(x):\n    if x = 5:\n        return \"five\"\n    return \"not five\"\n', 'def check(x):\n    if x == 5:\n        return \"five\"\n    return \"not five\"\n', 'function', 'check', '`=` and `==` look similar but do very different jobs. `=` stores a value in a variable; `==` asks \"are these equal?\" and gives back `True` or `False`. Conditions always need the question, not the assignment.', 'Whenever you write an `if` or `while` condition, check for a single `=` - it should almost always be `==`.', NULL, 'published', '14b30efadffaf2c6b27b0f6199ef1e019ac41f3bc77fe863ceebde07380485a6', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (63, 'keyword-mixup', 6, 'Keyword Mixup', 8, 2, NULL, 'syntax', '`grade(score)` should return `\"Pass\"` if `score` is 50 or above, `\"Fail\"` if it\'s 0 or above but under 50, and `\"Invalid\"` otherwise.\n\nExample: `grade(70)` should return `\"Pass\"`.', 'def grade(score):\n    if score >= 50:\n        return \"Pass\"\n    elseif score >= 0:\n        return \"Fail\"\n    else:\n        return \"Invalid\"\n', 'def grade(score):\n    if score >= 50:\n        return \"Pass\"\n    elif score >= 0:\n        return \"Fail\"\n    else:\n        return \"Invalid\"\n', 'function', 'grade', 'Python\'s keywords are fixed, exact words - `elif`, `in`, `and`, `not`, and so on. Writing a keyword from a different language, or a plausible-looking variant, just gives Python an unrecognised word instead.', 'If you\'ve used another language before, double check Python\'s exact keyword spelling rather than assuming it matches.', NULL, 'published', '4165c3e494882aa07be32df718a6f42c732b38fb63b411a045bd58d396a5efeb', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (64, 'wrong-brackets', 6, 'Wrong Brackets', 9, 2, NULL, 'runtime', '`shout(word)` should return `word` in uppercase.\n\nExample: `shout(\"hello\")` should return `\"HELLO\"`.', 'def shout(word):\n    result = word.upper[]\n    return result\n', 'def shout(word):\n    result = word.upper()\n    return result\n', 'function', 'shout', '`()`, `[]` and `{}` all mean different things in Python: calling, indexing, and sets/dicts respectively. Using the wrong bracket type usually still runs - it just does something else entirely, or crashes with a type error.', 'When calling a method or function, it\'s always round brackets `()`, even with nothing inside them.', NULL, 'published', '1dded55d171d9ca033e6b09f4b052f442f49ba0de67f5f4fbedc5484e6a8dcdf', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (65, 'unfinished-function', 6, 'Unfinished Function', 10, 1, NULL, 'syntax', '`square(n)` should return `n` multiplied by itself.\n\nExample: `square(4)` should return `16`.', 'def square n:\n    return n * n\n', 'def square(n):\n    return n * n\n', 'function', 'square', 'A function definition always follows the same shape: `def`, a name, parentheses around the parameters, then a colon. Missing any one of those pieces means Python can\'t parse the line at all.', 'Check every `def` line has the full shape: `def name(params):`.', NULL, 'published', 'f456cd30cd94daf0c3da428fe63d1a3fb593d3534d590ab53dfb15cd3f9d136b', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (66, 'mystery-name', 7, 'Mystery Name', 1, 1, NULL, 'runtime', '`greet(name)` should return a greeting like `\"Hello, Ada!\"`.\n\nExample: `greet(\"Ada\")` should return `\"Hello, Ada!\"`.', 'def greet(name):\n    message = \"Hello, \" + nmae + \"!\"\n    return message\n', 'def greet(name):\n    message = \"Hello, \" + name + \"!\"\n    return message\n', 'function', 'greet', 'Python only recognises a name once it\'s been created - it doesn\'t guess what you meant. A typo in a variable name looks right to the eye but is a completely different, undefined name to Python, so it crashes as soon as that line runs.', 'When you see a `NameError`, compare the named variable letter-by-letter against where it was created.', NULL, 'published', '8fa305c3f67692f3251ec0c811c8fc4e5621645d9217c298a69935975e20e568', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (67, 'text-plus-number', 7, 'Text Plus Number', 2, 1, NULL, 'runtime', '`describe_age(age)` should return a string like `\"Age: 17\"`.\n\nExample: `describe_age(17)` should return `\"Age: 17\"`.', 'def describe_age(age):\n    return \"Age: \" + age\n', 'def describe_age(age):\n    return \"Age: \" + str(age)\n', 'function', 'describe_age', 'Python\'s `+` operator means something different depending on the types either side of it: joining for two strings, addition for two numbers. Mixing a string and a number directly leaves Python unable to decide which you meant.', 'Before joining a value to a string with `+`, check its type - numbers need `str()` first.', NULL, 'published', 'f7b12336f99fc507d5bc05fddefc57bc8d25268c01ee6c6b53c45ee8101aab0a', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (68, 'past-the-end', 7, 'Past the End', 3, 2, NULL, 'runtime', '`last_item(items)` should return the last item in the list `items`.\n\nExample: `last_item([1, 2, 3])` should return `3`.', 'def last_item(items):\n    return items[len(items)]\n', 'def last_item(items):\n    return items[len(items) - 1]\n', 'function', 'last_item', 'A list of length `n` has valid indexes `0` through `n - 1`. `len(items)` is one more than the last valid index, so using it directly always lands one step past the end.', 'Whenever you index with `len(...)`, check whether you need to subtract 1.', NULL, 'published', 'caad02ab90ce55e08a5e7e723ad378f40038bbe7b3e5ca04cd44ab2f0e4d7032', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (69, 'missing-key', 7, 'Missing Key', 4, 2, NULL, 'runtime', '`get_colour(fruit)` should return the colour of `fruit`, or `\"unknown\"` if it isn\'t in the list.\n\nExample: `get_colour(\"apple\")` should return `\"red\"`.', 'def get_colour(fruit):\n    colours = {\"apple\": \"red\", \"banana\": \"yellow\"}\n    return colours[fruit]\n', 'def get_colour(fruit):\n    colours = {\"apple\": \"red\", \"banana\": \"yellow\"}\n    return colours.get(fruit, \"unknown\")\n', 'function', 'get_colour', '`dict[key]` crashes with `KeyError` if the key isn\'t present. `.get(key, default)` checks safely and returns the default instead, which is almost always what you want when the key might be missing.', 'Any time you index a dictionary with something that didn\'t come from iterating its own keys, consider `.get()` instead.', NULL, 'published', '7a07ad9f1998bcfe1fc61746b75d145ec28501af4c6c9e5b60b9e8cf76785710', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (70, 'divide-by-nothing', 7, 'Divide by Nothing', 5, 2, NULL, 'runtime', '`average(nums)` should return the mean of the numbers in `nums`, or `0` if the list is empty.\n\nExample: `average([2, 4, 6])` should return `4`.', 'def average(nums):\n    return sum(nums) / len(nums)\n', 'def average(nums):\n    if len(nums) == 0:\n        return 0\n    return sum(nums) / len(nums)\n', 'function', 'average', 'Dividing by zero always crashes in Python. Any time a divisor comes from a count that could be zero - like the length of a list - it needs a guard before the division runs.', 'Ask \"could this count ever be zero?\" for every division, and test with an empty input to check.', NULL, 'published', '6a947c268ccf7c3d800b60c4a85dfab8ae80bfd21a9285f414996e3547dc3211', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (71, 'not-a-number', 7, 'Not a Number', 6, 2, NULL, 'runtime', '`to_whole(text)` should convert a piece of text like `\"3\"` or `\"3.5\"` into a whole number, rounding down.\n\nExample: `to_whole(\"3.5\")` should return `3`.', 'def to_whole(text):\n    return int(text)\n', 'def to_whole(text):\n    return int(float(text))\n', 'function', 'to_whole', '`int(text)` requires the text to look like a whole number already. Text containing a decimal point needs `float()` first, which `int()` can then round down.', 'If text might contain a decimal point, convert with `float()` before `int()`.', NULL, 'published', '5c3e19597c15f27c03f473d740a31976a227a88cbfcf424f4f5b791efbecccb3', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (72, 'nothing-returned', 7, 'Nothing Returned', 7, 1, NULL, 'runtime', '`add(a, b)` should return the sum of `a` and `b`.\n\nExample: `add(2, 3)` should return `5`.', 'def add(a, b):\n    total = a + b\n', 'def add(a, b):\n    total = a + b\n    return total\n', 'function', 'add', 'A function that doesn\'t hit a `return` statement gives back `None` automatically - computing a value inside a function does nothing on its own unless it\'s returned.', 'If a function\'s result always seems to be `None`, check it actually has a `return` on the path that runs.', NULL, 'published', 'cb7de63f179a96347c859f484fc71d81bfe82866e7a0278e0487285e7d944785', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (73, 'local-trouble', 7, 'Local Trouble', 8, 3, NULL, 'runtime', 'This program keeps a running `count` and should print `1` then `2`.\n\nExample output:\n```\n1\n2\n```', 'count = 0\n\ndef increment():\n    count = count + 1\n    return count\n\nprint(increment())\nprint(increment())\n', 'count = 0\n\ndef increment():\n    global count\n    count = count + 1\n    return count\n\nprint(increment())\nprint(increment())\n', 'script', NULL, 'Python decides whether a name is local or global by scanning the whole function for assignments - not line by line. Assigning to `count` anywhere inside `increment` makes every use of `count` in that function local, which crashes if it reads `count` before any local assignment has happened.', 'If a function needs to update a variable from outside it, add `global name` at the top of the function.', NULL, 'published', 'd9a9d7decdf3153798abc37b14f1cc77e36d4fd961904c0ceb07ee2610e2a926', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (74, 'string-that-looked-like-a-number', 7, 'The String That Looked Like a Number', 9, 2, NULL, 'runtime', '`total_cost(price_text, quantity)` should return the cost of `quantity` items at the price given in `price_text` (a string, as if it came from `input()`), plus a flat ┬ú5 delivery fee.\n\nExample: `total_cost(\"4\", 3)` should return `17`.', 'def total_cost(price_text, quantity):\n    return price_text * quantity + 5\n', 'def total_cost(price_text, quantity):\n    return int(price_text) * quantity + 5\n', 'function', 'total_cost', 'Text that *looks* like a number is still text until it\'s explicitly converted. `input()` always returns a string, which is exactly why this bug is so common in real programs - multiplying text by a number repeats it instead of doing arithmetic.', 'If a value could have come from `input()` or another text source, check it\'s been converted before doing arithmetic with it.', NULL, 'published', '1891e8a9c2e87fabf02beb2f206dd3f4f4c2fbb672895e3bf010f4b5ee340c11', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (75, 'wrong-number-of-arguments', 7, 'Wrong Number of Arguments', 10, 2, NULL, 'runtime', '`greet(first_name, last_name)` should return a greeting using both names.\n\nExample: `greet(\"Ada\", \"Lovelace\")` should return `\"Hello, Ada Lovelace!\"`.', 'def greet(name):\n    return \"Hello, \" + name + \"!\"\n', 'def greet(first_name, last_name):\n    return \"Hello, \" + first_name + \" \" + last_name + \"!\"\n', 'function', 'greet', 'A function\'s parameter list is a contract: every call must supply exactly the arguments it\'s defined to accept (unless defaults are used). A mismatch between how a function is defined and how it\'s meant to be used is a `TypeError` waiting to happen.', 'When a `TypeError` mentions argument counts, compare the `def` line to every place the function is called or tested.', NULL, 'published', 'ca942b4f30ef35e8da48add6eea2264f5a7841b772f47b242f43135b8c443a4d', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (76, 'sum-to-n-off-by-one', 8, 'The Missing Number', 1, 2, NULL, 'logic', '`sum_to(n)` should return the sum of all whole numbers from 1 up to and including `n`.\n\nExample: `sum_to(4)` should return `10` (1 + 2 + 3 + 4).', 'def sum_to(n):\n    total = 0\n    for i in range(1, n):\n        total += i\n    return total\n', 'def sum_to(n):\n    total = 0\n    for i in range(1, n + 1):\n        total += i\n    return total\n', 'function', 'sum_to', 'Python\'s `range(a, b)` includes `a` but excludes `b` - a deliberate design choice that trips almost everyone up at least once. Whenever a loop should include the upper value, add one to the second argument.', 'Any time you loop with `range`, check the first and last values by hand with a tiny input like `n = 1` or `n = 2`.', 'What do you think `sum_to(4)` returns? Write it down before you run anything.', 'published', 'c2cce40ef041d810d878a68da015a43af8c9b0d5a1a112bad5741ddb7f2f0d96', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (77, 'fence-posts', 8, 'Fence Posts', 2, 2, NULL, 'logic', 'A straight fence needs one post at the start, then one more post per section. `posts_needed(sections)` should return the number of posts needed for a fence with that many sections.\n\nExample: `posts_needed(4)` should return `5`.', 'def posts_needed(sections):\n    return sections\n', 'def posts_needed(sections):\n    return sections + 1\n', 'function', 'posts_needed', 'This is the classic \"fencepost\" off-by-one: counting the gaps (sections) isn\'t the same as counting the boundaries between them (posts). Drawing a tiny example (1 or 2 sections) on paper makes the relationship obvious.', 'For anything involving counting items versus counting the gaps between them, sketch a tiny example by hand first.', 'If a fence has 4 sections, how many posts does it need? Write your answer down before running anything.', 'published', '4fff50b46110b3c2d452ba52d1b79b80c4a34859cf195784e062178f2c4aa7fb', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (78, 'half-a-result', 8, 'Half a Result', 3, 2, NULL, 'logic', '`average_two(a, b)` should return the exact average of `a` and `b`.\n\nExample: `average_two(3, 4)` should return `3.5`.', 'def average_two(a, b):\n    return (a + b) // 2\n', 'def average_two(a, b):\n    return (a + b) / 2\n', 'function', 'average_two', '`/` always gives the exact, possibly-fractional result. `//` rounds down to a whole number, discarding whatever came after the decimal point. They look almost identical but behave very differently.', 'Test division with numbers that don\'t divide evenly - that\'s when `//` versus `/` shows up clearly.', NULL, 'published', 'a9633fd518a8aeb7c7917a8674129cbc088829abff7c08e28e548d9aa302bb12', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (79, 'average-trouble', 8, 'Average Trouble', 4, 2, NULL, 'logic', '`average_two(a, b)` should return the average of `a` and `b`.\n\nExample: `average_two(4, 6)` should return `5`.', 'def average_two(a, b):\n    return a + b / 2\n', 'def average_two(a, b):\n    return (a + b) / 2\n', 'function', 'average_two', 'Python follows the normal maths order of operations: multiplication and division happen before addition and subtraction, unless brackets say otherwise. `a + b / 2` means `a + (b / 2)`, not `(a + b) / 2`.', 'When a calculation mixes `+`/`-` with `*`/`/`, add brackets to make the intended order explicit, even when you\'re confident of the rules.', NULL, 'published', 'fe253e7f3d3006e39ddf763304d23027a7b027e4bc7bda4bbcf4232bc783384c', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (80, 'and-or-or', 8, 'And or Or', 5, 2, NULL, 'logic', 'A valid username is between 3 and 20 characters long (inclusive). `is_valid_username(name)` should return `True` or `False` accordingly.\n\nExample: `is_valid_username(\"al\")` should return `False` (too short).', 'def is_valid_username(name):\n    return len(name) >= 3 or len(name) <= 20\n', 'def is_valid_username(name):\n    return len(name) >= 3 and len(name) <= 20\n', 'function', 'is_valid_username', '`or` is true if *either* side is true; `and` needs *both*. A validator that should enforce a range on both ends almost always needs `and`, since `or` lets almost everything through.', 'When a validator seems to accept things it shouldn\'t, check every `or` - would `and` be stricter and more correct?', NULL, 'published', 'e172c3cadc1b2707b1b1e9e6fb2f7873ee83bbb7759c912a0c31be6620a6f713', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (81, 'too-early-to-return', 8, 'Too Early to Return', 6, 3, NULL, 'logic', '`find_first_even(nums)` should return the first even number in `nums`, or `None` if there isn\'t one.\n\nExample: `find_first_even([1, 3, 4, 5])` should return `4`.', 'def find_first_even(nums):\n    for n in nums:\n        if n % 2 == 0:\n            return n\n        return None\n', 'def find_first_even(nums):\n    for n in nums:\n        if n % 2 == 0:\n            return n\n    return None\n', 'function', 'find_first_even', 'A `return` immediately exits the function, from wherever it is. Put one inside a loop by mistake, and it can end the search after checking just one item instead of letting the loop run its course.', 'Check what\'s actually inside a loop versus after it by reading the indentation carefully, not just the order lines appear on the page.', NULL, 'published', 'a3ce5ef37187d42991bc5607acd642d9b6c9c0750aecc20e3b899c21c192a7a8', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (82, 'forgot-to-reset', 8, 'Forgot to Reset', 7, 3, NULL, 'logic', '`sum_each(lists)` should return a list containing the sum of each inner list in `lists`.\n\nExample: `sum_each([[1, 2], [3, 4]])` should return `[3, 7]`.', 'def sum_each(lists):\n    total = 0\n    results = []\n    for lst in lists:\n        for num in lst:\n            total += num\n        results.append(total)\n    return results\n', 'def sum_each(lists):\n    results = []\n    for lst in lists:\n        total = 0\n        for num in lst:\n            total += num\n        results.append(total)\n    return results\n', 'function', 'sum_each', 'An accumulator variable needs resetting at the start of each new thing it\'s accumulating for. Initialise it outside a loop that\'s meant to restart it each time, and the totals bleed into each other.', 'For every accumulator, ask: \"does this get reset exactly where I need a fresh start?\"', NULL, 'published', 'bda4ab8d6463123f70abe19713cbbf67fa0e44f3e8b0f1298ccc40bd6f7d473b', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (83, 'the-loop-that-never-ends', 8, 'The Loop That Never Ends', 8, 2, NULL, 'logic', '`count_down(n)` should return a list counting down from `n` to `1`.\n\nExample: `count_down(3)` should return `[3, 2, 1]`.', 'def count_down(n):\n    result = []\n    while n > 0:\n        result.append(n)\n    return result\n', 'def count_down(n):\n    result = []\n    while n > 0:\n        result.append(n)\n        n -= 1\n    return result\n', 'function', 'count_down', 'Every `while` loop needs something inside it that moves its condition towards becoming false. Forgetting the update step - like decreasing a counter - leaves the condition permanently true.', 'For every `while` loop, find the line that changes the condition\'s variable. If there isn\'t one, that\'s the bug.', NULL, 'published', '3d3194e5533b3478043b6fb2a09837cb3d90e8df9c11ee4a32e25701bc642f83', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (84, 'ten-is-less-than-nine', 8, 'Ten Is Less Than Nine', 9, 3, NULL, 'logic', '`bigger(a, b)` takes two numbers written as text (as if read from `input()`) and returns the larger one as a number.\n\nExample: `bigger(\"10\", \"9\")` should return `10`.', 'def bigger(a, b):\n    if a > b:\n        return a\n    return b\n', 'def bigger(a, b):\n    a, b = int(a), int(b)\n    if a > b:\n        return a\n    return b\n', 'function', 'bigger', 'Comparing strings compares them character by character, the way a dictionary is ordered - `\"10\"` comes before `\"9\"` because `\"1\"` comes before `\"9\"`. Numbers written as text need converting before a numeric comparison makes sense.', 'If values might be text (especially from `input()`), check they\'re converted before comparing them as numbers.', NULL, 'published', '67322d8cb73cb48e28ab0b458dcc18cb24aeae595d9e1cba0b50be1b0a6752ef', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (85, 'shadowed', 8, 'Shadowed', 10, 3, NULL, 'runtime', '`total_of_unique(items)` should return the sum of the unique numbers in `items`.\n\nExample: `total_of_unique([1, 2, 2, 3])` should return `6`.', 'def total_of_unique(items):\n    sum = 0\n    unique = []\n    for item in items:\n        if item not in unique:\n            unique.append(item)\n    return sum(unique)\n', 'def total_of_unique(items):\n    unique = []\n    for item in items:\n        if item not in unique:\n            unique.append(item)\n    return sum(unique)\n', 'function', 'total_of_unique', 'Python lets you name a variable the same as a built-in function - `sum`, `list`, `str`, `type` are common ones - but doing so hides the built-in everywhere in that scope from that point on. If you need the real one later, the shadowed name causes a crash.', 'Avoid naming variables after built-in functions you might need later in the same function - `total` instead of `sum`, `items` instead of `list`.', NULL, 'published', '60c0751ef4377dd5b15df4a175df8277327a545a592c343e4de44e5af3fde678', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (86, 'modify-while-looping', 8, 'Modify While Looping', 11, 3, NULL, 'logic', '`remove_negatives(nums)` should return `nums` with every negative number removed.\n\nExample: `remove_negatives([1, -2, -3, 4])` should return `[1, 4]`.', 'def remove_negatives(nums):\n    for n in nums:\n        if n < 0:\n            nums.remove(n)\n    return nums\n', 'def remove_negatives(nums):\n    return [n for n in nums if n >= 0]\n', 'function', 'remove_negatives', 'When you remove an item from a list mid-iteration, everything after it shifts one position earlier - but the loop\'s position doesn\'t shift back to match, so it can silently skip the next item. Building a new list avoids the problem entirely.', 'Never remove items from a list (or dict) while iterating over that same list - build a new one or iterate over a copy instead.', NULL, 'published', '6e21ff18e4f4db554cf2be839ecc9c7bf352e709b40e3fdd4b1b60a5ae152a2c', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (87, 'case-matters', 8, 'Case Matters', 12, 2, NULL, 'logic', '`count_vowels(text)` should count how many vowels (a, e, i, o, u) are in `text`, regardless of case.\n\nExample: `count_vowels(\"APPLE\")` should return `2`.', 'def count_vowels(text):\n    count = 0\n    for ch in text:\n        if ch in \"aeiou\":\n            count += 1\n    return count\n', 'def count_vowels(text):\n    count = 0\n    for ch in text:\n        if ch.lower() in \"aeiou\":\n            count += 1\n    return count\n', 'function', 'count_vowels', 'Character comparisons in Python are case-sensitive - `\'A\' == \'a\'` is `False`. Converting both sides to the same case with `.lower()` (or `.upper()`) before comparing handles this cleanly.', 'When comparing text, test with a mix of uppercase and lowercase input to check case is handled the way you expect.', NULL, 'published', '7a1c8f67b9fb05dce5c115d2bc58819322018a3c151152657a9ded20fd0d9a51', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (88, 'infinite-descent', 9, 'Infinite Descent', 1, 3, NULL, 'runtime', '`factorial(n)` should return `n!` (n factorial): `n * (n-1) * (n-2) * ... * 1`.\n\nExample: `factorial(5)` should return `120`. By definition, `factorial(0)` and `factorial(1)` both return `1`.', 'def factorial(n):\n    return n * factorial(n - 1)\n', 'def factorial(n):\n    if n <= 1:\n        return 1\n    return n * factorial(n - 1)\n', 'function', 'factorial', 'Recursive functions need two things: a base case that returns without recursing, and a recursive case that\'s guaranteed to move closer to that base case. This function only has the recursive case, so it never stops - it just keeps calling itself with smaller and smaller numbers until Python gives up.', 'Whenever you write a recursive function, write the base case first and check the recursive call actually moves towards it.', 'What do you think happens when you run `factorial(5)`? Will it finish? Write down what you expect before you run it.', 'published', '8cda8441bd441b79d4348d243b274fe7f2358ded3914d0f00021ccb64686a5ad', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (89, 'shared-default', 9, 'Shared Default', 2, 3, NULL, 'logic', 'Each call to `add_item` should start from a fresh, empty basket unless one is given.\n\nExpected output:\n```\n[\'apple\']\n[\'banana\']\n```', 'def add_item(item, basket=[]):\n    basket.append(item)\n    return basket\n\nprint(add_item(\"apple\"))\nprint(add_item(\"banana\"))\n', 'def add_item(item, basket=None):\n    if basket is None:\n        basket = []\n    basket.append(item)\n    return basket\n\nprint(add_item(\"apple\"))\nprint(add_item(\"banana\"))\n', 'script', NULL, 'A default argument value is evaluated exactly once, when `def` runs - not fresh on every call. For an immutable default like a number or string this never matters, but a mutable default like a list or dict gets shared and silently mutated across every call that relies on it.', 'Never use a mutable value (`[]`, `{}`, a class instance) as a default argument - use `None` and create the real default inside the function body instead.', 'Each call leaves out the `basket` argument. What do you expect the two printed lines to look like?', 'published', '2d78064811ca3aa88e97a29acd15016cb3925e5f55dce354e16f48535ea5d6b5', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (90, 'same-list-two-names', 9, 'Same List, Two Names', 3, 3, NULL, 'logic', 'Doubling a copy of a list should leave the original list unchanged.\n\nExpected output:\n```\n[1, 2, 3]\n[2, 4, 6]\n```', 'original = [1, 2, 3]\ndoubled = original\nfor i in range(len(doubled)):\n    doubled[i] = doubled[i] * 2\nprint(original)\nprint(doubled)\n', 'original = [1, 2, 3]\ndoubled = original.copy()\nfor i in range(len(doubled)):\n    doubled[i] = doubled[i] * 2\nprint(original)\nprint(doubled)\n', 'script', NULL, 'Assigning a list to a new name doesn\'t copy it - both names point at the exact same object in memory. Changing the contents through either name changes what both names see, which is surprising if you expected an independent copy.', 'If you need a genuinely separate list, use `.copy()`, `list(...)`, or a slice `[:]` - plain `=` never copies a list.', 'After `doubled = original`, are `original` and `doubled` separate lists, or two names for the same one? What do you expect printed?', 'published', '631841c23f9f6f2b0691361d6b266d14f96284af7059a436f2e28c82118db40d', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (91, 'grid-surprise', 9, 'Grid Surprise', 4, 4, NULL, 'logic', 'Changing one cell of a grid should only affect that one cell.\n\nExpected output:\n```\n[[1, 0, 0], [0, 0, 0], [0, 0, 0]]\n```', 'grid = [[0] * 3] * 3\ngrid[0][0] = 1\nprint(grid)\n', 'grid = [[0] * 3 for _ in range(3)]\ngrid[0][0] = 1\nprint(grid)\n', 'script', NULL, 'Multiplying a list with `*` repeats references to the same object, not independent copies - this is harmless for immutable items like numbers, but for a list-of-lists, every \"row\" ends up being the exact same row, aliased three times over.', 'Never build a 2D grid with `[[...] * n] * m` - use a comprehension so each row is created fresh.', 'After `grid[0][0] = 1`, how many of the 9 cells do you expect to show `1`?', 'published', 'aad26edd514fa5f1814e44f59b8e304ebb026f46c2a966151563eef29a6686fc', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (92, 'the-search-that-hangs', 9, 'The Search That Hangs', 5, 4, NULL, 'logic', '`binary_search(items, target)` should return the index of `target` in the sorted list `items`, or `-1` if it isn\'t there.\n\nExample: `binary_search([1, 3, 5, 7, 9], 7)` should return `3`.', 'def binary_search(items, target):\n    low, high = 0, len(items)\n    while low < high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid\n        else:\n            high = mid\n    return -1\n', 'def binary_search(items, target):\n    low, high = 0, len(items) - 1\n    while low <= high:\n        mid = (low + high) // 2\n        if items[mid] == target:\n            return mid\n        elif items[mid] < target:\n            low = mid + 1\n        else:\n            high = mid - 1\n    return -1\n', 'function', 'binary_search', 'Binary search relies on the search range shrinking every single pass. If a new bound is set to `mid` itself rather than one step past it, the range can stop shrinking entirely when the target isn\'t in the list - looping forever instead of giving up.', 'For any loop meant to narrow down a range, check by hand that the range can\'t get stuck at the same size pass after pass.', NULL, 'published', '9e3b4c7e6fad8345fca5c1ba78b0077225e6bfd6ce8c7cb151086b2c0ff07260', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (93, 'late-binding', 9, 'Late Binding', 6, 4, NULL, 'logic', 'Each function made in the loop should remember its *own* value of `i` at the time it was created.\n\nExpected output:\n```\n[0, 1, 2]\n```', 'makers = []\nfor i in range(3):\n    makers.append(lambda: i)\nprint([m() for m in makers])\n', 'makers = []\nfor i in range(3):\n    makers.append(lambda i=i: i)\nprint([m() for m in makers])\n', 'script', NULL, 'A closure remembers the *variable*, not the value it held at creation time. Since all three lambdas share the same loop variable `i`, and the loop has finished by the time any of them are called, they all see `i`\'s final value. A default argument is evaluated once, at creation, which is how to capture the value instead.', 'If you create functions inside a loop that need to remember the loop variable\'s value, capture it with a default argument: `lambda x=x: ...`.', 'Three lambdas are created, one per loop iteration. What do you expect calling all three, in order, to give?', 'published', '8416e56bc0e9651ca3521b3316d160fe0da0047e19b26c18758e39d4fbbf9561', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (94, 'global-mistake', 9, 'Global Mistake', 7, 3, NULL, 'logic', '`record_score` should remember the highest score seen so far, across separate calls.\n\nExpected output:\n```\n50\n50\n80\n```', 'high_score = 0\n\ndef record_score(points):\n    local_high = high_score\n    if points > local_high:\n        local_high = points\n    return local_high\n\nprint(record_score(50))\nprint(record_score(30))\nprint(record_score(80))\n', 'high_score = 0\n\ndef record_score(points):\n    global high_score\n    if points > high_score:\n        high_score = points\n    return high_score\n\nprint(record_score(50))\nprint(record_score(30))\nprint(record_score(80))\n', 'script', NULL, 'Reading a global variable into a local one copies its current value - it doesn\'t create a live link back to the original. Without `global`, any \"updates\" only change the local copy, which disappears when the function returns, leaving the real global untouched.', 'If a function needs to remember something between separate calls, it has to update a genuine global (with `global`) - a local copy resets every time.', 'Three scores are recorded in a row: 50, then 30, then 80. What do you expect printed each time?', 'published', 'caedc6ab358244af587b488d96946b0c5924de6e695916b41f6c24df03f054bf', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (95, 'used-up', 9, 'Used Up', 8, 4, NULL, 'logic', 'Listing the same filtered results twice should give the same answer both times.\n\nExpected output:\n```\n[2, 4, 6]\n[2, 4, 6]\n```', 'def even_numbers(nums):\n    return (n for n in nums if n % 2 == 0)\n\nevens = even_numbers([1, 2, 3, 4, 5, 6])\nprint(list(evens))\nprint(list(evens))\n', 'def even_numbers(nums):\n    return [n for n in nums if n % 2 == 0]\n\nevens = even_numbers([1, 2, 3, 4, 5, 6])\nprint(list(evens))\nprint(list(evens))\n', 'script', NULL, 'Generators produce values lazily, one at a time, and don\'t remember them afterwards - once consumed, they\'re exhausted for good. A list holds all its values at once and can be read repeatedly, which is what\'s needed here.', 'If something needs to be iterated over more than once, make sure it\'s a list (or another reusable collection), not a one-shot generator.', '`list(evens)` is called twice on the same `evens`. What do you expect the second call to print?', 'published', 'e8c742acbb814da1a7833b8aa47913a2843a673df9c755f070d22d272c76c55d', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (96, 'nearly-equal', 9, 'Nearly Equal', 9, 3, NULL, 'logic', '`adds_to_one(a, b, c)` should return `True` if the three numbers add up to (very close to) `1`.\n\nExample: `adds_to_one(0.7, 0.2, 0.1)` should return `True`.', 'def adds_to_one(a, b, c):\n    return a + b + c == 1.0\n', 'import math\n\ndef adds_to_one(a, b, c):\n    return math.isclose(a + b + c, 1.0)\n', 'function', 'adds_to_one', 'Computers store `float` numbers in binary, and most decimal fractions (like 0.1) can\'t be represented exactly in binary any more than 1/3 can be written exactly in decimal. The tiny rounding errors this creates mean exact equality (`==`) between floats is almost never the right check.', 'Never compare floats with `==` - use `math.isclose()` (or check the difference is smaller than a small tolerance) instead.', 'Do you expect `0.7 + 0.2 + 0.1` to be exactly equal to `1.0` in Python? Write down yes or no before running it.', 'published', '5bf2aab5c63b64dd7dd5e392024da80beda327a09b2f31a9996692ba4352993d', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (97, 'changing-while-iterating-dict', 9, 'Changing While Iterating', 10, 4, NULL, 'runtime', '`remove_zero_stock(stock)` should remove any item from the `stock` dictionary whose count is `0`, and return the dictionary.\n\nExample: `remove_zero_stock({\"pens\": 0, \"pencils\": 5})` should return `{\"pencils\": 5}`.', 'def remove_zero_stock(stock):\n    for item in stock:\n        if stock[item] == 0:\n            del stock[item]\n    return stock\n', 'def remove_zero_stock(stock):\n    for item in list(stock.keys()):\n        if stock[item] == 0:\n            del stock[item]\n    return stock\n', 'function', 'remove_zero_stock', 'Unlike lists, Python actively detects a dictionary changing size while you iterate over it and raises an error rather than risk silently skipping or revisiting items. Looping over a separate list of the keys (taken before the loop starts) sidesteps the problem entirely.', 'Never add or remove keys from a dict while iterating directly over it - loop over `list(d.keys())` if you need to modify it as you go.', NULL, 'published', '04c77145e6f7f84cffd032f231c7fa1210cb37107ddf2a37d89d28b57a5f852c', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (98, 'sorted-wrong', 9, 'Sorted Wrong', 11, 3, NULL, 'logic', '`top_scorers(players)` takes a list of `(name, score)` tuples and should return the names of the 3 highest scorers, highest first.\n\nExample: `top_scorers([(\"Al\", 10), (\"Bo\", 30), (\"Cy\", 20), (\"Di\", 5)])` should return `[\"Bo\", \"Cy\", \"Al\"]`.', 'def top_scorers(players):\n    ranked = sorted(players, key=lambda p: p[1])\n    return [name for name, score in ranked[:3]]\n', 'def top_scorers(players):\n    ranked = sorted(players, key=lambda p: p[1], reverse=True)\n    return [name for name, score in ranked[:3]]\n', 'function', 'top_scorers', '`sorted()` always sorts ascending (smallest first) unless told otherwise. Taking a slice from the front after sorting ascending gives you the smallest items, which is the opposite of \"top\" unless `reverse=True` is added.', 'After any `sorted()` call, check whether you want ascending or descending order, and whether `reverse=True` matches that.', NULL, 'published', 'c96c3ebe0c88c28ce451189a6fbfdffbba9aa1b40715d4cd28b068d39952fa2c', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (99, 'silent-failure', 9, 'Silent Failure', 12, 4, NULL, 'logic', '`safe_divide(a, b)` should return `a` divided by `b`.\n\nExample: `safe_divide(10, 2)` should return `5.0`.', 'def safe_divide(a, b):\n    try:\n        resutl = a / b\n        return result\n    except:\n        return None\n', 'def safe_divide(a, b):\n    return a / b\n', 'function', 'safe_divide', 'A bare `except:` catches every exception, including the ones you never intended to - like a plain typo. That turns a loud, obvious crash (which would have pointed straight at the mistake) into a silent wrong answer, which is much harder to track down.', 'Avoid bare `except:` - catch only the specific exception types you actually expect, so unexpected bugs stay loud instead of disappearing silently.', NULL, 'published', '3e202917d57036990d54c2b47c830e925075870015958591cb58b42f6c108c6b', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (100, 'equal-or-identical', 9, 'Equal or Identical', 13, 3, NULL, 'logic', '`same_contents(a, b)` should return `True` if two lists contain the same items in the same order, even if they are different list objects.\n\nExample: `same_contents([1, 2, 3], [1, 2, 3])` should return `True`.', 'def same_contents(a, b):\n    return a is b\n', 'def same_contents(a, b):\n    return a == b\n', 'function', 'same_contents', '`==` asks \"do these have the same value?\"; `is` asks \"are these the exact same object in memory?\" Two separately built lists can hold identical values while being two completely different objects - which is the normal, expected case, not an edge case.', 'Use `==` to compare values (almost always what you want); reserve `is` for checking against `None` or confirming two names refer to the literal same object.', NULL, 'published', '9468ff7d79f67edee7cc7b2bd450032cbe01e9f8c5350295f115bf9cf18aae12', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (101, 'grade-calculator', 10, 'Grade Calculator', 1, 4, NULL, 'mixed', '`calculate_grade(scores)` takes a list of test scores (0-100) and returns a grade:\n\n- `\"Distinction\"` if the average is 70 or above\n- `\"Pass\"` if the average is 50 or above (but below 70)\n- `\"Fail\"` otherwise\n- `\"No scores\"` if the list is empty\n\nExample: `calculate_grade([85, 90, 95])` should return `\"Distinction\"`.', 'def calculate_grade(scores):\n    total = 0\n    for score in scores:\n        total = total + score\n    average = total / len(scores)\n    if average > 70:\n        return \"Distinction\"\n    elif average > 50:\n        return \"Pass\"\n    else:\n        return \"Fail\"\n', 'def calculate_grade(scores):\n    if len(scores) == 0:\n        return \"No scores\"\n    total = 0\n    for score in scores:\n        total = total + score\n    average = total / len(scores)\n    if average >= 70:\n        return \"Distinction\"\n    elif average >= 50:\n        return \"Pass\"\n    else:\n        return \"Fail\"\n', 'function', 'calculate_grade', 'Two separate bugs here. First, dividing by `len(scores)` crashes on an empty list because there\'s no guard for that case. Second, `>` silently excludes the boundary value itself - the brief says \"70 or above\", which means `>=`, not `>`. Neither bug stops the other from being tested, so fixing one doesn\'t reveal the other automatically - you need to check both the empty case and the exact boundaries.', 'For any function with thresholds, test the exact boundary values by hand, and always ask what happens with an empty or missing input.', NULL, 'published', 'ceac46023d6e00ddb53fa86ed73cf3eaeae69912fbeaaa1e526640fc5f156c9b', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (102, 'caesar-cipher', 10, 'Caesar Cipher', 2, 4, NULL, 'mixed', '`encode(text, shift)` should shift every letter in `text` forward by `shift` places in the alphabet, wrapping around from Z back to A (and z back to a). Non-letter characters (spaces, punctuation) should be left unchanged, and case should be preserved.\n\nExample: `encode(\"abc\", 1)` should return `\"bcd\"`. `encode(\"xyz\", 3)` should return `\"abc\"` (wrapping around).', 'def encode(text, shift):\n    result = \"\"\n    for ch in text:\n        code = ord(ch) + shift\n        result += chr(code)\n    return result\n', 'def encode(text, shift):\n    result = \'\'\n    for ch in text:\n        if ch.isupper():\n            result += chr((ord(ch) - ord(\'A\') + shift) % 26 + ord(\'A\'))\n        elif ch.islower():\n            result += chr((ord(ch) - ord(\'a\') + shift) % 26 + ord(\'a\'))\n        else:\n            result += ch\n    return result\n', 'function', 'encode', 'Two bugs stack up here. Shifting by adding directly to the character code never wraps back around the alphabet - working in 0-25 alphabet positions with `% 26` fixes that. Separately, the code shifts *every* character, including spaces and punctuation, when only letters should move - those need an explicit check and a pass-through branch.', 'For cipher-style problems, test wraparound (shifting past \'z\') and non-letter characters (spaces, punctuation) as two separate boundary cases.', NULL, 'published', 'f30096f3a735a9e7be3bb8ac818429c8cddc3be37f6c7c39ebd177d055124450', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (103, 'tic-tac-toe-winner', 10, 'Tic-Tac-Toe Winner', 3, 4, NULL, 'logic', '`winner(board)` takes a 3x3 list of lists, where each cell is `\"X\"`, `\"O\"`, or `\"\"`. It should return `\"X\"` or `\"O\"` if that player has three in a row (row, column, or diagonal), `\"Draw\"` if the board is full with no winner, or `None` if the game is still in progress.\n\nExample: a board with `\"X\"` down the main diagonal and nothing else should return `\"X\"`.', 'def winner(board):\n    for row in board:\n        if row[0] == row[1] == row[2] != \'\':\n            return row[0]\n    for col in range(3):\n        if board[0][col] == board[1][col] == board[2][col] != \'\':\n            return board[0][col]\n    return None\n', 'def winner(board):\n    lines = []\n    for row in board:\n        lines.append(row)\n    for col in range(3):\n        lines.append([board[0][col], board[1][col], board[2][col]])\n    lines.append([board[0][0], board[1][1], board[2][2]])\n    lines.append([board[0][2], board[1][1], board[2][0]])\n    for line in lines:\n        if line[0] == line[1] == line[2] != \'\':\n            return line[0]\n    if all(cell != \'\' for row in board for cell in row):\n        return \'Draw\'\n    return None\n', 'function', 'winner', 'Tic-tac-toe has 8 possible winning lines - 3 rows, 3 columns, and 2 diagonals - and missing any category means some genuine wins go undetected. Separately, \"no winner found\" isn\'t the same as \"game over\" - a full board with no three-in-a-row is a draw, which needs its own explicit check.', 'For a grid-based game, list every possible winning line on paper first, then check your code actually covers each one.', NULL, 'published', 'd2f4d3c0128491508f57568cc6cbae78abad574d9e0dc3b84d0aede13e611730', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (104, 'bank-account', 10, 'Bank Account', 4, 5, NULL, 'mixed', 'An `Account` class should track its own balance and its own list of transactions independently from every other account, and should refuse to withdraw more than the current balance.\n\n`run_bank_demo(initial_a, initial_b, withdraw_amount)` creates two accounts, withdraws `withdraw_amount` from the first, and returns `(account_a.balance, account_b.balance, len(account_b.transactions))`.', 'class Account:\n    transactions = []\n\n    def __init__(self, balance=0):\n        self.balance = balance\n\n    def withdraw(self, amount):\n        self.balance -= amount\n        self.transactions.append(amount)\n        return self.balance\n\n\ndef run_bank_demo(initial_a, initial_b, withdraw_amount):\n    a = Account(initial_a)\n    b = Account(initial_b)\n    a.withdraw(withdraw_amount)\n    return [a.balance, b.balance, len(b.transactions)]\n', 'class Account:\n    def __init__(self, balance=0):\n        self.balance = balance\n        self.transactions = []\n\n    def withdraw(self, amount):\n        if amount > self.balance:\n            raise ValueError(\"Insufficient funds\")\n        self.balance -= amount\n        self.transactions.append(amount)\n        return self.balance\n\n\ndef run_bank_demo(initial_a, initial_b, withdraw_amount):\n    a = Account(initial_a)\n    b = Account(initial_b)\n    a.withdraw(withdraw_amount)\n    return [a.balance, b.balance, len(b.transactions)]\n', 'function', 'run_bank_demo', 'A mutable value defined directly under `class Account:` (rather than inside `__init__` with `self.`) is a class attribute, shared by every single instance - exactly the same trap as a mutable default argument, just in a different place. Separately, a withdrawal method that never checks the balance first will happily go negative, which real bank accounts should never allow.', 'Any mutable value (a list, dict, or another object) defined directly under a class line, not inside `__init__` with `self.`, is shared across every instance - give each instance its own copy in `__init__` instead.', NULL, 'published', 'c1760400678fdbc4ad310121c279866e89d47bb3b8edf051772eeb289770a6f9', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (105, 'inventory-manager', 10, 'Inventory Manager', 5, 4, NULL, 'mixed', '`process_orders(stock, orders)` takes a stock dictionary (item name to quantity) and a list of `(item, quantity)` orders. It should reduce stock for each order, ignore orders for items not in stock, and return `(updated_stock, total_sold)`.\n\nExample: `process_orders({\"apples\": 10, \"pears\": 5}, [(\"apples\", 3)])` should return `({\"apples\": 7, \"pears\": 5}, 3)`.', 'def process_orders(stock, orders):\n    total_sold = 0\n    for item, qty in orders:\n        stock[item] -= qty\n        stock[item] -= qty\n        total_sold += qty\n    return [stock, total_sold]\n', 'def process_orders(stock, orders):\n    total_sold = 0\n    for item, qty in orders:\n        if item not in stock:\n            continue\n        stock[item] -= qty\n        total_sold += qty\n    return [stock, total_sold]\n', 'function', 'process_orders', 'Two independent bugs here: a straightforwardly duplicated line that silently double-counts every sale, and a missing guard for orders that reference stock that doesn\'t exist. Neither bug masks the other - fixing the duplicate still leaves the `KeyError` waiting for the next test that orders something unstocked.', 'Read every line as if it might be an accidental duplicate, especially inside a loop - and always test with an input that references something that doesn\'t exist yet.', NULL, 'published', '8a3a193554648f15a4008b6aed48cd4cf2263ee66ae368747260161333269e44', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (106, 'prime-sieve', 10, 'Prime Sieve', 6, 5, NULL, 'logic', '`primes_up_to(n)` should return a list of every prime number from 2 up to and including `n`.\n\nExample: `primes_up_to(10)` should return `[2, 3, 5, 7]`.', 'def primes_up_to(n):\n    is_prime = [True] * n\n    is_prime[0] = False\n    for i in range(2, n):\n        if is_prime[i]:\n            for multiple in range(i * 2, n, i):\n                is_prime[multiple] = False\n    return [i for i in range(n) if is_prime[i]]\n', 'def primes_up_to(n):\n    is_prime = [True] * (n + 1)\n    is_prime[0] = is_prime[1] = False\n    for i in range(2, n + 1):\n        if is_prime[i]:\n            for multiple in range(i * i, n + 1, i):\n                is_prime[multiple] = False\n    return [i for i in range(n + 1) if is_prime[i]]\n', 'function', 'primes_up_to', 'This classic algorithm has two boundary mistakes stacked together: the list size and loop bounds don\'t reach the upper limit `n` itself (an inclusive-range off-by-one), and `1` - which is not prime by definition - is never explicitly excluded the way `0` is.', 'For range-based algorithms, always test the smallest and largest values your range is supposed to include, by hand.', NULL, 'published', '67edda7487e3fbd25e8f33a75b9e7a58c5c1486c5b828565836a6a3df6b65d30', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (107, 'merge-sort', 10, 'Merge Sort', 7, 5, NULL, 'logic', '`merge_sort(items)` should return a new list containing every item from `items`, sorted in ascending order.\n\nExample: `merge_sort([5, 2, 4, 1, 3])` should return `[1, 2, 3, 4, 5]`.', 'def merge_sort(items):\n    if len(items) <= 1:\n        return items\n    mid = len(items) // 2\n    left = merge_sort(items[:mid])\n    right = merge_sort(items[mid:])\n    merged = []\n    i = j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            merged.append(left[i])\n            i += 1\n        else:\n            merged.append(right[j])\n            j += 1\n    return merged\n', 'def merge_sort(items):\n    if len(items) <= 1:\n        return items\n    mid = len(items) // 2\n    left = merge_sort(items[:mid])\n    right = merge_sort(items[mid:])\n    merged = []\n    i = j = 0\n    while i < len(left) and j < len(right):\n        if left[i] <= right[j]:\n            merged.append(left[i])\n            i += 1\n        else:\n            merged.append(right[j])\n            j += 1\n    merged.extend(left[i:])\n    merged.extend(right[j:])\n    return merged\n', 'function', 'merge_sort', 'The classic merge step compares the fronts of two already-sorted halves one at a time - but it only keeps comparing while *both* halves still have items left. The moment one half runs dry, the loop exits, and anything still waiting in the other half needs to be tacked on afterwards - a step that\'s easy to forget since the function \"looks finished\" without it.', 'After any loop that processes two lists in lockstep, check: could one list still have leftover items when the loop ends? If so, they need handling separately.', NULL, 'published', '30e5277c11f847b0913126692287dcffd6ba67d285066427f3d4e4940c274173', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (108, 'linked-list', 10, 'Linked List', 8, 5, NULL, 'logic', 'Reversing a linked list should produce the same values in reverse order.\n\n`reverse_to_list(values)` builds a linked list from `values`, reverses it, and returns the result as a plain Python list.\n\nExample: `reverse_to_list([1, 2, 3, 4])` should return `[4, 3, 2, 1]`.', 'class Node:\n    def __init__(self, value, next=None):\n        self.value = value\n        self.next = next\n\n\ndef reverse(head):\n    prev = None\n    current = head\n    while current:\n        current.next = prev\n        prev = current\n        current = current.next\n    return prev\n\n\ndef reverse_to_list(values):\n    head = None\n    for v in reversed(values):\n        head = Node(v, head)\n    reversed_head = reverse(head)\n    result = []\n    node = reversed_head\n    while node:\n        result.append(node.value)\n        node = node.next\n    return result\n', 'class Node:\n    def __init__(self, value, next=None):\n        self.value = value\n        self.next = next\n\n\ndef reverse(head):\n    prev = None\n    current = head\n    while current:\n        next_node = current.next\n        current.next = prev\n        prev = current\n        current = next_node\n    return prev\n\n\ndef reverse_to_list(values):\n    head = None\n    for v in reversed(values):\n        head = Node(v, head)\n    reversed_head = reverse(head)\n    result = []\n    node = reversed_head\n    while node:\n        result.append(node.value)\n        node = node.next\n    return result\n', 'function', 'reverse_to_list', 'Reversing a linked list in place needs to remember where to go next *before* changing the pointer that normally tells you that. Overwrite `current.next` first, and the very next line that tries to follow it is actually following the just-changed pointer, not the original list - losing everything after the first node.', 'When reassigning a pointer/reference you still need to read from, save the original value in a temporary variable first.', NULL, 'published', '671f58841a4d425f4f195eff0ea5c50ccbfc70f1f2d14c8a33f469f638df2ca9', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (109, 'text-statistics', 10, 'Text Statistics', 9, 4, NULL, 'mixed', '`text_stats(text)` should return a dictionary `{\"word_count\": ..., \"avg_word_length\": ...}` describing the words in `text`, ignoring surrounding punctuation. An empty (or whitespace-only) `text` should return `{\"word_count\": 0, \"avg_word_length\": 0}`.\n\nExample: `text_stats(\"Hello, world!\")` should return `{\"word_count\": 2, \"avg_word_length\": 5.0}` (ignoring the comma and exclamation mark).', 'def text_stats(text):\n    words = text.split()\n    return {\"word_count\": len(words), \"avg_word_length\": sum(len(w) for w in words) / len(words)}\n', 'def text_stats(text):\n    words = text.split()\n    if not words:\n        return {\"word_count\": 0, \"avg_word_length\": 0}\n    cleaned = [w.strip(\'.,!?;:\"\\\'\') for w in words]\n    return {\"word_count\": len(cleaned), \"avg_word_length\": sum(len(w) for w in cleaned) / len(cleaned)}\n', 'function', 'text_stats', 'Splitting text into words is the easy part - the real care is in what counts as a \"word\" (should trailing punctuation count towards its length?) and what happens for degenerate input like an empty string, which needs its own explicit, non-crashing answer.', 'For any text-processing function, test with punctuation attached to words, and with empty or whitespace-only input.', NULL, 'published', 'c224887fc57f3fc4e45c364b3f2a048de25298f137d37916230082cbdb666278', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_puzzles` VALUES (110, 'shopping-cart', 10, 'Shopping Cart', 10, 4, NULL, 'logic', '`total_cost(prices, discount_percent)` should add up `prices`, then apply a percentage discount to the total, rounded to 2 decimal places.\n\nExample: `total_cost([10, 20], 10)` should return `27.0` (30 total, minus 10%).', 'def total_cost(prices, discount_percent):\n    total = sum(prices)\n    discount = total - discount_percent / 100\n    return round(total - discount, 2)\n', 'def total_cost(prices, discount_percent):\n    total = sum(prices)\n    discount = total * (discount_percent / 100)\n    return round(total - discount, 2)\n', 'function', 'total_cost', 'A percentage discount needs to scale *with* the total - doubling the total should double the discount amount too. A formula built from subtraction instead of multiplication breaks that relationship entirely, and the wrongness is easy to miss unless you check a concrete example by hand.', 'For any calculation involving a percentage, sanity-check it on a round, easy number by hand (like 10% of 30) before trusting the formula.', NULL, 'published', 'c0b51f24513338eb363ddac9f3020286f7cd5d3025ea3719c164b357fa956fbc', '2026-11-21 16:47:43', NULL, '2026-11-21 16:47:43', '2026-11-21 16:47:43');
INSERT INTO `bh_tracks` VALUES (6, 'spot-the-typo', 'Spot the Typo', 'Syntax errors: the code won\'t even run yet.', 'Every puzzle here fails before it even starts. You\'ll learn to read `SyntaxError` and `IndentationError` messages and fix the shape of the code, not its logic.', 'syntax', 'none', 1, 'published');
INSERT INTO `bh_tracks` VALUES (7, 'crash-course', 'Crash Course', 'Runtime errors: the code runs, then crashes partway through.', 'These puzzles run until something goes wrong. You\'ll learn to read a traceback from the bottom up and recognise what each exception type is telling you.', 'runtime', 'basic', 2, 'published');
INSERT INTO `bh_tracks` VALUES (8, 'wrong-answer', 'Wrong Answer', 'The code runs fine and gives you a confidently wrong answer.', 'No errors here - just the wrong result. You\'ll compare expected vs actual output and get used to checking boundary values by hand.', 'logic', 'full', 3, 'published');
INSERT INTO `bh_tracks` VALUES (9, 'deep-bugs', 'Deep Bugs', 'Subtler logic bugs that need a trace table to really see.', 'These bugs hide in state, scope and recursion. You\'ll use trace tables and variable watch to see what\'s really happening, step by step.', 'logic', 'full', 4, 'published');
INSERT INTO `bh_tracks` VALUES (10, 'boss-fights', 'Boss Fights', 'Bigger programs with more than one bug hiding in them.', 'Multiple bugs, longer code. You\'ll divide and conquer, build minimal examples, and work the full debugging loop end to end.', 'mixed', 'full', 5, 'published');
